# -*- coding: utf-8 -*-
HTML_TEMPLATE = '<!DOCTYPE html>\n<html lang="es">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Laboratorio de Estudio de Diabetes para Enfermería — Dr. Marcos Gamond</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap" rel="stylesheet">\n  <link rel="stylesheet" href="/static/css/diaguias.css?v=5.7" />\n</head>\n<body>\n\n  <!-- BARRA SUPERIOR INSTITUCIONAL CON EL CÍRCULO AZUL DE LA DIABETES -->\n  <header class="header-bar">\n    <div class="brand-box">\n      <img src="/static/assets/circulo_azul_diabetes.svg" alt="Círculo Azul de la Diabetes" class="brand-emblem-img" />\n      <div class="brand-text-wrap">\n        <div class="brand-eyebrow">\n          <span>✨ ESCUELA DE EDUCACIÓN EN DIABETES</span>\n          <span class="brand-dot">•</span>\n          <span>PROGRAMA DE 60 HS CÁTEDRA</span>\n        </div>\n        <h1>LABORATORIO DE ESTUDIO DE DIABETES PARA ENFERMERÍA</h1>\n        <p><span class="director-pill">👨\u200d⚕️ Dirección Académica: Dr. Marcos Gamond</span> <span class="brand-sub-guia">Guías Clínicas ADA • SAD • MSAL • FITTER • IWGDF</span></p>\n      </div>\n    </div>\n\n    <div class="progress-pill">\n      <div>\n        <div style="font-size:0.7rem; color:#bae6fd; font-weight:700; letter-spacing:0.03em;">AVANCE DEL CURSO</div>\n        <div id="globalProgressText" style="font-size:0.84rem; font-weight:800;">0 / 10 Unidades (0%)</div>\n      </div>\n      <div class="progress-track">\n        <div id="globalProgressBar" class="progress-fill"></div>\n      </div>\n    </div>\n\n    <nav class="nav-pills">\n      <button class="nav-btn active" onclick="openTab(\'tabCampus\', this)">🎓 Programa (10 Unidades)</button>\n      <button class="nav-btn" onclick="openTab(\'tabAlgoritmos\', this)">🧭 Algoritmos de Guardia</button>\n      <button class="nav-btn" onclick="openTab(\'tabCalculadoras\', this)">🧮 Calculadoras Clínicas</button>\n      <button class="nav-btn" onclick="openTab(\'tabCopiloto\', this)">🩺 Tutor GLUC-IA</button>\n      <button class="nav-btn" style="background:rgba(251,191,36,0.18); border-color:rgba(251,191,36,0.55); color:#fef08a;" onclick="abrirModalGlosarioSiglas()">📖 Siglas y Abreviaturas</button>\n    </nav>\n  </header>\n\n  <main class="workspace">\n\n    <!-- ======================================================================\n         PESTAÑA 1: CAMPUS ASINCRÓNICO COMPLETO (10 UNIDADES + ESTUDIO NOTEBOOKLM)\n         ====================================================================== -->\n    <section id="tabCampus" class="view-pane active">\n      <div class="campus-layout">\n\n        <!-- SIDEBAR IZQUIERDO: LAS 10 UNIDADES DEL PROGRAMA -->\n        <aside class="units-sidebar">\n          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">\n            <strong style="font-size:0.92rem; color:#0f172a;">📋 Plan de Estudios (60 hs)</strong>\n            <button class="quick-chip" style="font-size:0.72rem; padding:4px 8px;" onclick="resetearProgreso()">Reiniciar</button>\n          </div>\n          <div id="unitsSidebarList"></div>\n        </aside>\n\n        <!-- ESCENARIO DERECHO: CONTENIDO DE LA UNIDAD SELECCIONADA -->\n        <div class="unit-stage">\n          <!-- ENCABEZADO ELEGANTE DE LA UNIDAD CON MINI-IMAGEN CLÍNICA COMPACTA -->\n          <div class="unit-header-card">\n            <div class="unit-header-main">\n              <img id="unitHeroPhoto" src="/static/assets/paciente_internacion.jpg" alt="Escena Clínica de la Unidad" class="unit-mini-thumb" />\n              <div class="unit-title-content">\n                <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:4px;">\n                  <span class="tag-sigla" style="margin-bottom:0;" id="unitModuloBadge">Módulo</span>\n                  <span class="tag-sigla" style="background:#dcfce7; color:#15803d; margin-bottom:0;" id="unitDuracionBadge">6 hs cátedra</span>\n                  <div id="unitApprovalStamp" style="margin-left:auto;"></div>\n                </div>\n                <h2 id="unitMainTitle" class="unit-main-heading">Cargando unidad...</h2>\n                <p id="unitMainResumen" class="unit-main-subtitle"></p>\n              </div>\n            </div>\n\n            <!-- SEMÁFORO CLÍNICO INTEGRADO DEBAJO DEL TÍTULO -->\n            <div class="unit-traffic-strip" id="unitVisualShowcase">\n              <div class="traffic-meters" id="unitTrafficMeters"></div>\n            </div>\n\n            <!-- REFERENCIA RÁPIDA DE SIGLAS Y ABREVIATURAS DE ESTA UNIDAD -->\n            <div class="unit-siglas-box">\n              <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px; margin-bottom:6px;">\n                <span style="font-size:0.74rem; font-weight:800; color:#0369a1; text-transform:uppercase; letter-spacing:0.03em;">\n                  🔤 Referencia Rápida de Siglas y Abreviaturas de esta Unidad:\n                </span>\n                <button class="quick-chip" style="font-size:0.72rem; padding:3px 10px; background:#e0f2fe; color:#0369a1; border-color:#7dd3fc; font-weight:800;" onclick="abrirModalGlosarioSiglas()">\n                  📖 Ver Diccionario Completo de Siglas (A–Z)\n                </button>\n              </div>\n              <div id="unitSiglasContainer" class="unit-siglas-pills"></div>\n            </div>\n          </div>\n\n          <!-- MAPA VISUAL DE 4 BLOQUES DE LA UNIDAD (SIN SOBRECARGAR) -->\n          <div class="visual-strip-4" id="unitVisualStrip4"></div>\n\n          <!-- 5 PASOS PEDAGÓGICOS DENTRO DE LA UNIDAD + ACCESO RÁPIDO AL TUTOR IA -->\n          <div class="unit-subtabs">\n            <button class="subtab-btn active" onclick="switchUnitStep(\'stepMedia\', this)">\n              🎬 1. Presentación, Podcast, Video & Infografía\n            </button>\n            <button class="subtab-btn" onclick="switchUnitStep(\'stepFisio\', this)">\n              📖 2. Fisiopatología Aplicada\n            </button>\n            <button class="subtab-btn" onclick="switchUnitStep(\'stepGuias\', this)">\n              📚 3. Guías y Consensos (ADA/SAD)\n            </button>\n            <button class="subtab-btn" onclick="switchUnitStep(\'stepCaso\', this)">\n              🩺 4. Caso Clínico\n            </button>\n            <button class="subtab-btn" onclick="switchUnitStep(\'stepQuiz\', this)">\n              📝 5. Autoevaluación\n            </button>\n            <button class="subtab-btn" style="background:linear-gradient(135deg,#0284c7,#1d4ed8); color:#fff; border:none;" onclick="abrirCopilotoEnUnidadActual()">\n              🩺 Consultar a GLUC-IA sobre esta Unidad\n            </button>\n          </div>\n\n          <!-- PASO 1: HUB MULTIMEDIA NOTEBOOKLM (PRESENTACIÓN + INFOGRAFÍA + PODCAST + VIDEO + LECTURA 3 MIN) -->\n          <div id="stepMedia" class="unit-step-pane">\n\n            <!-- REPRODUCTOR PRINCIPAL DE VIDEO NOTEBOOKLM (SE MUESTRA AUTOMÁTICAMENTE APENAS HAY VIDEO CARGADO EN LA UNIDAD) -->\n            <div id="topUnitVideoBanner" style="display:none; background:linear-gradient(135deg,#0f172a,#1e293b); border:2px solid #10b981; border-radius:16px; padding:16px 20px; margin-bottom:16px; color:#fff;">\n              <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:10px;">\n                <span class="tag-sigla" style="background:#10b981; color:#052e16; font-weight:800;">🎬 VIDEO-PRESENTACIÓN OFICIAL NOTEBOOKLM ACTIVA EN ESTA UNIDAD</span>\n                <span style="font-size:0.8rem; color:#a7f3d0; font-weight:700;">▶️ Dale Play para ver la clase audiovisual de la unidad</span>\n              </div>\n              <video id="topUnitVideoPlayer" controls style="width:100%; max-height:380px; border-radius:12px; background:#000;"></video>\n            </div>\n\n            <!-- BARRA RÁPIDA DE RECURSO MULTIMEDIA (4 FORMATOS VISUALES) -->\n            <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:16px;">\n              <button class="quick-chip" style="background:#e0f2fe; border-color:#0284c7; font-weight:800;" onclick="switchMediaSubView(\'viewSlides\')">\n                🖥️ Presentación (5 Diapositivas)\n              </button>\n              <button class="quick-chip" style="background:#dcfce7; border-color:#10b981; font-weight:800;" onclick="switchMediaSubView(\'viewInfografia\')">\n                🖼️ Infografía Visual de Guardia\n              </button>\n              <button class="quick-chip" style="background:#fef3c7; border-color:#f59e0b; font-weight:800;" onclick="switchMediaSubView(\'viewPodcastVideo\')">\n                🎙️ Podcast & Video-Clase\n              </button>\n              <button class="quick-chip" style="background:#f3e8ff; border-color:#9333ea; font-weight:800;" onclick="switchMediaSubView(\'viewUploadNLM\')">\n                📤 Cargar mis Archivos de NotebookLM\n              </button>\n            </div>\n\n            <div class="grid-2col">\n\n              <!-- COLUMNA IZQUIERDA DINÁMICA: PRESENTACIÓN / INFOGRAFÍA / PODCAST-VIDEO / SUBIDA -->\n              <div>\n\n                <!-- SUB-VISTA A: PRESENTACIÓN DE 5 DIAPOSITIVAS INTERACTIVAS -->\n                <div id="viewSlides" class="media-subview" style="background:linear-gradient(135deg,#0f172a,#1e3a8a); color:#fff; border-radius:16px; padding:24px; min-height:310px; display:flex; flex-direction:column; justify-content:space-between;">\n                  <div>\n                    <div style="display:flex; justify-content:space-between; align-items:center;">\n                      <span class="tag-sigla" style="background:#38bdf8; color:#0f172a;" id="slideCounterBadge">DIAPOSITIVA 1 DE 5</span>\n                      <span style="font-size:0.76rem; color:#93c5fd;">Presentación Lista para Proyectar o Grabar</span>\n                    </div>\n                    <h3 id="slideTitleText" style="color:#fff; font-size:1.22rem; margin-top:12px;">Título de Diapositiva</h3>\n                    <div id="slideBodyText" style="font-size:0.95rem; color:#e2e8f0; margin-top:12px; white-space:pre-line; line-height:1.7;"></div>\n                  </div>\n\n                  <div style="display:flex; justify-content:space-between; align-items:center; margin-top:22px; padding-top:14px; border-top:1px solid rgba(255,255,255,0.15);">\n                    <button class="nav-btn" onclick="changeSlide(-1)">⬅ Anterior</button>\n                    <button class="nav-btn active" onclick="reproducirSlideActualVoz()">🔊 Narrar Diapositiva</button>\n                    <button class="nav-btn" onclick="changeSlide(1)">Siguiente ➔</button>\n                  </div>\n\n                  <!-- Si subió un PDF de presentación a la unidad, botón para abrirlo -->\n                  <div id="uploadedPdfBanner" style="display:none; margin-top:12px; background:rgba(16,185,129,0.2); padding:10px; border-radius:8px; text-align:center;">\n                    <a id="uploadedPdfLink" href="#" target="_blank" style="color:#34d399; font-weight:800; font-size:0.85rem;">📄 Abrir Presentación PDF Subida de esta Unidad ↗</a>\n                  </div>\n                </div>\n\n                <!-- SUB-VISTA B: INFOGRAFÍA VISUAL EN 4 BLOQUES + IMAGEN SUBIDA -->\n                <div id="viewInfografia" class="media-subview" style="display:none; background:#0f172a; color:#fff; border-radius:16px; padding:22px;">\n                  <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:12px;">\n                    <span class="tag-sigla" style="background:#10b981; color:#052e16;">🖼️ INFOGRAFÍA RESUMEN DE 1 VISTAZO</span>\n                    <div style="display:flex; gap:8px; flex-wrap:wrap;">\n                      <button class="quick-chip" style="font-size:0.74rem; background:#fef3c7; color:#92400e; border-color:#f59e0b; font-weight:800;" onclick="copiarPromptInfografiaUnidad()">📋 Copiar Prompt Infografía</button>\n                      <button class="quick-chip" style="font-size:0.74rem; background:#e0f2fe; color:#0369a1; border-color:#0284c7; font-weight:800;" onclick="imprimirInfografiaCompleta()">🖨️ Imprimir Infografía (Página Completa)</button>\n                    </div>\n                  </div>\n                  <div id="copyInfografiaFeedbackMsg" style="font-size:0.76rem; color:#fde047; margin-bottom:8px; display:none;"></div>\n\n                  <!-- Si subió imagen de infografía desde NotebookLM/Canva, se muestra acá -->\n                  <div id="uploadedInfografiaBox" style="display:none; margin-bottom:14px;">\n                    <img id="uploadedInfografiaImg" src="" alt="Infografía de la Unidad" style="width:100%; border-radius:12px; border:2px solid #38bdf8;" />\n                  </div>\n\n                  <div id="infografiaBuiltInGrid" style="display:grid; grid-template-columns:1fr 1fr; gap:12px;"></div>\n                </div>\n\n                <!-- SUB-VISTA C: PODCAST DE AUDIO Y VIDEO-CLASE -->\n                <div id="viewPodcastVideo" class="media-subview" style="display:none; background:#0f172a; color:#f8fafc; border-radius:16px; padding:22px;">\n                  <div style="display:flex; justify-content:space-between; align-items:center;">\n                    <span class="tag-sigla" style="background:#f59e0b; color:#0f172a;">🎙️ PODCAST NOTEBOOKLM & VIDEO-CLASE</span>\n                    <span id="mediaDurationBadge" style="font-size:0.78rem; color:#38bdf8; font-weight:800;">05:30 min</span>\n                  </div>\n\n                  <h3 id="mediaTitleText" style="color:#fff; font-size:1.08rem; margin-top:8px;">Micro-Clase de la Unidad</h3>\n\n                  <div style="display:flex; gap:10px; flex-wrap:wrap; margin-top:12px;">\n                    <button class="nav-btn active" style="padding:10px 16px;" onclick="reproducirMicroClaseVoz()">\n                      🔊 Escuchar Clase Narrada por IA Ahora\n                    </button>\n                    <button class="nav-btn" style="padding:10px 14px;" onclick="detenerMicroClaseVoz()">\n                      ⏹️ Detener\n                    </button>\n                  </div>\n\n                  <div style="margin-top:14px; padding:12px; background:rgba(255,255,255,0.06); border-radius:12px;">\n                    <div style="font-size:0.78rem; color:#7dd3fc; font-weight:700; margin-bottom:6px;">\n                      🎧 Podcast NotebookLM de esta Unidad:\n                    </div>\n                    <audio id="unitPodcastAudio" controls style="width:100%; height:36px;"></audio>\n                  </div>\n\n                  <div id="videoPlayerContainer" style="display:none; margin-top:14px;">\n                    <div style="font-size:0.78rem; color:#34d399; font-weight:700; margin-bottom:6px;">\n                      🎬 Video-Clase Cargada:\n                    </div>\n                    <video id="unitVideoPlayer" controls style="width:100%; border-radius:10px; max-height:240px;"></video>\n                  </div>\n\n                  <details style="margin-top:14px; background:rgba(255,255,255,0.05); padding:12px; border-radius:10px; cursor:pointer;">\n                    <summary style="font-size:0.84rem; font-weight:700; color:#38bdf8;">\n                      📜 Ver Guion Teleprompter Completo\n                    </summary>\n                    <p id="mediaScriptText" style="font-size:0.88rem; color:#e2e8f0; margin-top:10px; line-height:1.6;"></p>\n                  </details>\n                </div>\n\n                <!-- SUB-VISTA D: FLUJO RÁPIDO NOTEBOOKLM (DESCARGAR FUENTE -> SUBIR RESULTADOS EN 1 CLIC) -->\n                <div id="viewUploadNLM" class="media-subview" style="display:none; background:#0f172a; color:#f8fafc; border-radius:16px; padding:22px;">\n                  <span class="tag-sigla" style="background:#a855f7; color:#fff;">🚀 ESTUDIO RÁPIDO NOTEBOOKLM (3 PASOS)</span>\n                  <h3 style="color:#fff; font-size:1.06rem; margin-top:8px;">Armá y subí el Podcast, Video o Infografía en 2 minutos:</h3>\n\n                  <div id="uploadedFilesBadgesBox" style="display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;"></div>\n\n                  <div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:12px;">\n                    <a id="btnDownloadNotebookLM" href="#" download class="quick-chip" style="text-decoration:none; background:#10b981; color:#052e16; border:none; font-weight:800;">\n                      ⬇️ Paso 1: Bajar Dossier .MD de la Unidad\n                    </a>\n                    <button class="quick-chip" onclick="copiarPromptNotebookLM()">\n                      📋 Paso 2: Copiar Prompt Argentino\n                    </button>\n                    <a href="https://notebooklm.google.com/" target="_blank" class="quick-chip" style="text-decoration:none;">\n                      🌐 Abrir NotebookLM ↗\n                    </a>\n                  </div>\n                  <div id="copyFeedbackMsg" style="font-size:0.76rem; color:#fde047; margin-top:6px; display:none;"></div>\n\n                  <div style="margin-top:16px; padding-top:14px; border-top:1px solid rgba(255,255,255,0.15);">\n                    <div style="font-size:0.84rem; font-weight:800; color:#38bdf8; margin-bottom:8px;">\n                      📤 Paso 3: Subí acá lo que descargaste de NotebookLM (detecta solo si es Video .mp4, Audio o Imagen):\n                    </div>\n\n                    <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px;">\n                      <select id="uploadMediaType" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569;">\n                        <option value="video">🎬 Video de la Unidad (.mp4)</option>\n                        <option value="podcast">🎙️ Podcast de Audio (.mp3 / .wav)</option>\n                        <option value="infografia">🖼️ Infografía Imagen (.png / .jpg)</option>\n                        <option value="presentacion">📄 Presentación (.pdf)</option>\n                      </select>\n                      <input type="file" id="uploadMediaFile" onchange="autoDetectMediaType(this)" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; padding:7px;" />\n                    </div>\n\n                    <button class="nav-btn active" style="width:100%; margin-top:10px; padding:11px;" onclick="subirArchivoNotebookLM()">\n                      ⬆️ Subir y Publicar en esta Unidad Ahora\n                    </button>\n                    <div id="uploadStatusMsg" style="font-size:0.82rem; color:#34d399; margin-top:8px; display:none;"></div>\n                  </div>\n\n                  <!-- PASO 4: REEMPLAZAR TEXTOS DE LA UNIDAD CON LO QUE GENERE TU NOTEBOOKLM -->\n                  <details style="margin-top:14px; background:rgba(255,255,255,0.06); padding:13px; border-radius:12px; cursor:pointer;">\n                    <summary style="font-size:0.84rem; font-weight:800; color:#34d399;">\n                      ✏️ Paso 4: Pegar/Reemplazar Textos con la Bibliografía de mi NotebookLM\n                    </summary>\n                    <div style="margin-top:10px; display:flex; flex-direction:column; gap:8px;">\n                      <label style="font-size:0.76rem; color:#cbd5e1;">Puntos de «Lectura Rápida en 3 Minutos» (1 punto por renglón):</label>\n                      <textarea id="editLectura3Min" class="calc-input" style="min-height:80px; background:#1e293b; color:#fff; border-color:#475569; font-size:0.83rem;"></textarea>\n\n                      <label style="font-size:0.76rem; color:#cbd5e1;">Regla Salvavidas / Regla de Oro de tu Bibliografía:</label>\n                      <input type="text" id="editReglaOro" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; font-size:0.83rem;" />\n\n                      <label style="font-size:0.76rem; color:#cbd5e1;">Síntesis / Apunte extraído de tu Cuaderno NotebookLM (se suma a Fisiopatología):</label>\n                      <textarea id="editBiblioExtra" class="calc-input" style="min-height:85px; background:#1e293b; color:#fff; border-color:#475569; font-size:0.83rem;" placeholder="Pegá acá el resumen o guía de estudio que te armó NotebookLM con tus PDFs..."></textarea>\n\n                      <button class="nav-btn active" style="padding:10px;" onclick="guardarTextoNotebookLM()">\n                        💾 Guardar y Reemplazar Textos en esta Unidad\n                      </button>\n                      <div id="editTextStatusMsg" style="font-size:0.8rem; color:#34d399; display:none;"></div>\n                    </div>\n                  </details>\n                </div>\n\n              </div>\n\n              <!-- COLUMNA DERECHA: FICHA DE LECTURA RÁPIDA EN 3 MINUTOS (SIEMPRE VISIBLE Y CORTITA) -->\n              <div style="background:#f8fafc; border:1.5px solid #cbd5e1; border-radius:16px; padding:20px;">\n                <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">\n                  <span class="tag-sigla" style="background:#fef3c7; color:#92400e;">⚡ LECTURA DE BOLSILLO EN 3 MINUTOS (SIN RELLENO)</span>\n                  <button class="quick-chip" style="font-size:0.75rem;" onclick="window.print()">🖨️ Imprimir 1 Carilla</button>\n                </div>\n\n                <h3 style="font-size:1.05rem; color:#0f172a; margin-top:6px;">\n                  Resumen ultra-corto para fijar antes de la guardia:\n                </h3>\n\n                <div id="lectura3MinContainer" style="margin-top:12px; display:flex; flex-direction:column; gap:10px;"></div>\n\n                <div class="gold-rule-box" style="margin-top:14px; margin-bottom:0;">\n                  <strong>🚨 Regla Salvavidas de la Unidad:</strong>\n                  <p id="mediaGoldRuleShort" style="margin-top:4px; font-size:0.86rem;"></p>\n                </div>\n              </div>\n\n            </div>\n\n            <div style="display:flex; justify-content:flex-end; margin-top:18px;">\n              <button class="subtab-btn active" onclick="goToNextUnitTab(1)">Profundizar en Fisiopatología Aplicada ➔</button>\n            </div>\n          </div>\n\n          <!-- PASO 2: FISIOPATOLOGÍA Y CONCEPTOS CLAVE -->\n          <div id="stepFisio" class="unit-step-pane" style="display:none;">\n            <div id="unitFisioContainer"></div>\n            <div style="display:flex; justify-content:flex-end; margin-top:16px;">\n              <button class="subtab-btn active" onclick="goToNextUnitTab(2)">Ir a Guías y Consensos de la Unidad ➔</button>\n            </div>\n          </div>\n\n          <!-- PASO 3: GUÍAS, CONSENSOS Y TABLA DE METAS -->\n          <div id="stepGuias" class="unit-step-pane" style="display:none;">\n            <span class="tag-sigla" id="unitGuiaFuente">Fuente Oficial</span>\n            <table class="consensus-table">\n              <thead>\n                <tr>\n                  <th>Parámetro / Situación Clínica</th>\n                  <th>Meta / Conducta Estándar</th>\n                  <th>Población Especial / Alerta</th>\n                  <th>Punto de Corte / Acción Crítica</th>\n                </tr>\n              </thead>\n              <tbody id="unitGuiaTablaBody"></tbody>\n            </table>\n\n            <div class="gold-rule-box">\n              <strong>⭐ Regla de Oro Operativa para Enfermería:</strong>\n              <p id="unitGuiaReglaOro" style="margin-top:5px;"></p>\n            </div>\n\n            <div style="display:flex; justify-content:flex-end; margin-top:16px;">\n              <button class="subtab-btn active" onclick="goToNextUnitTab(3)">Ir al Caso Clínico de la Unidad ➔</button>\n            </div>\n          </div>\n\n          <!-- PASO 4: CASO CLÍNICO INTERACTIVO DE LA UNIDAD -->\n          <div id="stepCaso" class="unit-step-pane" style="display:none;">\n            <div class="theory-card" style="border-left-color:#f59e0b; background:#fffbeb;">\n              <h4>🩺 Escenario Clínico Real para Enfermería</h4>\n              <p id="unitCasoEscenario" style="margin-top:6px; font-size:0.96rem;"></p>\n              <p id="unitCasoPregunta" style="margin-top:10px; font-weight:800; color:#92400e;"></p>\n            </div>\n\n            <button class="subtab-btn" onclick="document.getElementById(\'unitCasoResolucionBox\').style.display=\'block\'">\n              👁️ Revelar Resolución Basada en Fisiopatología y Guías\n            </button>\n\n            <div id="unitCasoResolucionBox" class="calc-result" style="display:none; margin-top:14px;">\n              <strong>✅ Fundamento Clínico y Conducta Enfermera:</strong>\n              <p id="unitCasoResolucion" style="margin-top:6px;"></p>\n            </div>\n\n            <div style="display:flex; justify-content:flex-end; margin-top:18px;">\n              <button class="subtab-btn active" onclick="goToNextUnitTab(4)">Rendir Autoevaluación de la Unidad 📝 ➔</button>\n            </div>\n          </div>\n\n          <!-- PASO 5: AUTOEVALUACIÓN CALIFICADA DE LA UNIDAD -->\n          <div id="stepQuiz" class="unit-step-pane" style="display:none;">\n            <div style="margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">\n              <div>\n                <h4 style="font-size:1.05rem;">📝 Autoevaluación Integradora de la Unidad</h4>\n                <p style="font-size:0.84rem; color:#64748b;">Respondé las 3 preguntas clínicas. Se aprueba con 2 o 3 respuestas correctas (≥ 67-70%).</p>\n              </div>\n            </div>\n\n            <div id="unitQuizQuestionsBox"></div>\n\n            <button class="nav-btn active" style="padding:12px 24px; font-size:0.92rem;" onclick="calificarAutoevaluacion()">\n              ✔️ Corregir Autoevaluación y Registrar Nota\n            </button>\n\n            <div id="unitQuizResultBanner" class="calc-result" style="display:none; margin-top:16px;"></div>\n          </div>\n\n        </div>\n      </div>\n    </section>\n\n    <!-- ======================================================================\n         PESTAÑA 2: ÁRBOLES DE DECISIÓN INTERACTIVOS PASO A PASO\n         ====================================================================== -->\n    <section id="tabAlgoritmos" class="view-pane">\n      <div class="section-banner">\n        <div>\n          <h2>🧭 Algoritmos Vivos de Decisión Clínica Paso a Paso</h2>\n          <p>Seleccioná la situación del paciente en sala y el árbol interactivo te guía nodo por nodo según el protocolo oficial ADA / SAD.</p>\n        </div>\n        <div style="display:flex; gap:8px;">\n          <button class="quick-chip" onclick="loadAlgorithm(\'algo_hipoglucemia\')">🍬 Protocolo Hipoglucemia (&lt;70 mg/dL)</button>\n          <button class="quick-chip" onclick="loadAlgorithm(\'algo_preoperatorio\')">🏥 Paciente a Cirugía / Contraste EV</button>\n        </div>\n      </div>\n\n      <div class="surface-card" style="max-width:920px; margin:0 auto;">\n        <span class="tag-sigla" id="algoGuiaTag">ADA / SAD</span>\n        <h3 id="algoMainTitle" style="font-size:1.25rem;">Algoritmo Interactivo</h3>\n\n        <div class="algo-step-box">\n          <h4 id="algoNodeQuestion" style="font-size:1.1rem; color:#0f172a;"></h4>\n          <p id="algoNodeContext" style="font-size:0.9rem; color:#334155; margin-top:8px;"></p>\n          <div id="algoOptionsContainer" style="margin-top:14px;"></div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ======================================================================\n         PESTAÑA 3: CALCULADORAS CLÍNICAS DE GUARDIA PARA ENFERMERÍA\n         ====================================================================== -->\n    <section id="tabCalculadoras" class="view-pane">\n      <div class="section-banner">\n        <div>\n          <h2>🧮 Calculadoras Clínicas de Guardia Basadas en Guías</h2>\n          <p>Herramientas prácticas de bolsillo para Bomba de Insulina EV en Cetoacidosis y Clasificación SINBAD de Pie Diabético.</p>\n        </div>\n      </div>\n\n      <div class="grid-2col">\n        <div class="surface-card">\n          <h3>💉 Calculadora 1: Bomba EV de Insulina en CAD y Seguridad de Potasio</h3>\n          <p style="font-size:0.84rem; color:#64748b; margin-bottom:14px;">\n            Calcula dosis horaria estándar ($0.1\\text{ UI/kg/h}$), dilución $1\\text{ ml} = 1\\text{ UI}$ y audita si es seguro iniciar según el Potasio ($\\text{K}^+$).\n          </p>\n\n          <div class="calc-group">\n            <label>Peso estimado del paciente (kg)</label>\n            <input type="number" id="calcPeso" class="calc-input" value="70" />\n          </div>\n          <div class="calc-group">\n            <label>Glucemia actual (mg/dL)</label>\n            <input type="number" id="calcGlucemia" class="calc-input" value="380" />\n          </div>\n          <div class="calc-group">\n            <label>Potasio sérico actual K+ (mEq/L)</label>\n            <input type="number" step="0.1" id="calcPotasio" class="calc-input" value="4.1" />\n          </div>\n\n          <button class="nav-btn active" style="width:100%; padding:12px;" onclick="calcularBombaEV()">\n            Calcular Indicación y Auditar Seguridad por Guía SAD/ADA\n          </button>\n\n          <div id="resBombaBox" class="calc-result"></div>\n        </div>\n\n        <div class="surface-card">\n          <h3>🦶 Calculadora 2: Clasificación SINBAD de Pie Diabético (Guía IWGDF / MSAL)</h3>\n          <p style="font-size:0.84rem; color:#64748b; margin-bottom:14px;">\n            Marcá los hallazgos presentes en el examen del pie para obtener el puntaje SINBAD (0 a 6) y la conducta de derivación.\n          </p>\n\n          <div style="display:flex; flex-direction:column; gap:9px; font-size:0.88rem;">\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>S (Sitio):</strong> Úlcera en mediopié o retropié/talón (+1 pt)</label>\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>I (Isquemia):</strong> Flujo arterial reducido / pulsos ausentes (+1 pt)</label>\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>N (Neuropatía):</strong> Sensibilidad al monofilamento 10g ausente (+1 pt)</label>\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>B (Bacterial Infection):</strong> Signos clínicos de infección / eritema / pus (+1 pt)</label>\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>A (Área):</strong> Úlcera $\\ge 1\\text{ cm}^2$ (+1 pt)</label>\n            <label><input type="checkbox" class="sinbad-chk" value="1" onchange="calcularSinbad()"> <strong>D (Depth / Profundidad):</strong> Llega a músculo, tendón o hueso (+1 pt)</label>\n          </div>\n\n          <div id="resSinbadBox" class="calc-result" style="margin-top:18px;"></div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ======================================================================\n         PESTAÑA 4: GLUC-IA — ASISTENTE CLÍNICO VIRTUAL PROPIO DEL CURSO\n         ====================================================================== -->\n    <section id="tabCopiloto" class="view-pane">\n      <div class="section-banner">\n        <div>\n          <h2>🩺 GLUC-IA • Tutor Clínico Virtual de Enfermería</h2>\n          <p>Asistente académico del <strong>Laboratorio de Estudio de Diabetes para Enfermería — Dr. Marcos Gamond</strong>. Consultá dudas de guardia, farmacología o fisiopatología de las 10 Unidades y las Guías Oficiales.</p>\n        </div>\n        <div style="display:flex; gap:8px; flex-wrap:wrap;">\n          <button class="quick-chip" onclick="narrarUltimaRespuestaCopiloto()">🔊 Escuchar Respuesta</button>\n          <button class="quick-chip" onclick="detenerMicroClaseVoz()">⏹️ Silenciar</button>\n          <button class="quick-chip" onclick="limpiarHistorialCopiloto()">🧹 Nueva Consulta</button>\n        </div>\n      </div>\n\n      <div class="campus-layout" style="grid-template-columns: 330px 1fr; gap: 18px; align-items: start;">\n\n        <!-- PANEL IZQUIERDO: SELECTOR DE UNIDAD / GUÍA Y MODO DE RESPUESTA -->\n        <aside class="units-sidebar" style="background:#0f172a; color:#f8fafc; border-color:#1e293b; padding:18px;">\n          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">\n            <span class="tag-sigla" style="background:#38bdf8; color:#0f172a; font-weight:800;">🩺 TUTOR VIRTUAL GLUC-IA</span>\n            <span style="font-size:0.72rem; color:#34d399; font-weight:700;">🟢 En línea</span>\n          </div>\n\n          <label style="font-size:0.78rem; color:#cbd5e1; font-weight:700; display:block; margin-bottom:6px;">\n            1. ¿Qué módulo o guía querés consultar?\n          </label>\n          <select id="ragScopeSelect" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; font-size:0.84rem; margin-bottom:14px;">\n            <option value="todas">🌐 Todo el Programa (10 Unidades + Guías Clínicas)</option>\n            <option value="solo_guias">🏛️ Solo Consensos Oficiales (ADA • SAD • MSAL • FITTER • IWGDF)</option>\n            <option value="u1">🔬 Unidad 1: Fisiopatología, Diagnóstico y HGT</option>\n            <option value="u2">📟 Unidad 2: DBT Tipo 1, Sensores CGM y Alba vs Somogyi</option>\n            <option value="u3">🫀 Unidad 3: DBT Tipo 2, Síndrome Metabólico y Adulto Frágil</option>\n            <option value="u4">🤰 Unidad 4: Diabetes Gestacional, Pedersen y Puerperio</option>\n            <option value="u5">🥗 Unidad 5: Nutrición (Plato) y Ejercicio (GLUT-4)</option>\n            <option value="u6">💉 Unidad 6: Insulinas, Cadena de Frío y Técnica FITTER</option>\n            <option value="u7">💊 Unidad 7: Antidiabéticos Orales, iSGLT2 y GLP-1</option>\n            <option value="u8">🚨 Unidad 8: Hipoglucemia, CAD, EHH y Bomba EV</option>\n            <option value="u9">🦶 Unidad 9: Pie Diabético (IWGDF / SINBAD) y Crónicas</option>\n            <option value="u10">🎓 Unidad 10: Educación Teach-Back y Regla SADMANS</option>\n          </select>\n\n          <label style="font-size:0.78rem; color:#cbd5e1; font-weight:700; display:block; margin-bottom:6px;">\n            2. ¿Cómo preferís la respuesta?\n          </label>\n          <select id="ragModeSelect" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; font-size:0.84rem; margin-bottom:14px;">\n            <option value="estudio">📖 Explicación Académica Completa (Fisiopatología y Guías)</option>\n            <option value="guardia">⚡ Conducta Rápida de Guardia (Paso a Paso)</option>\n            <option value="examen">📝 Practicar con un Caso Clínico de Autoevaluación</option>\n          </select>\n\n          <div style="background:rgba(56,189,248,0.1); border:1px solid rgba(56,189,248,0.3); border-radius:12px; padding:12px; font-size:0.79rem; color:#e2e8f0; line-height:1.5; margin-bottom:14px;">\n            💡 <strong>Evaluación de Casos Reales:</strong> Podés incluir datos de tu paciente en la consulta (ej.: <em>«Paciente de 80 kg en cetoacidosis con potasio de 2.9»</em> o <em>«HGT de 48 mg/dL somnoliento»</em>) y <strong>GLUC-IA</strong> calculará la conducta y las alertas de seguridad.\n          </div>\n\n          <!-- AGREGAR NUEVO PROTOCOLO O BIBLIOGRAFÍA DOCENTE -->\n          <details style="background:rgba(255,255,255,0.06); padding:12px; border-radius:12px; cursor:pointer;">\n            <summary style="font-size:0.8rem; font-weight:800; color:#34d399;">\n              ➕ Cargar Protocolo o Bibliografía Docente\n            </summary>\n            <div style="margin-top:10px; display:flex; flex-direction:column; gap:8px;">\n              <input type="text" id="newRagDocTitle" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; font-size:0.8rem;" placeholder="Título (ej: Protocolo de Guardia)" />\n              <input type="file" id="newRagDocFile" accept=".txt,.md,.csv" onchange="cargarArchivoTextoEnRagInput(this)" class="calc-input" style="background:#1e293b; color:#fff; border-color:#475569; font-size:0.75rem; padding:6px;" />\n              <textarea id="newRagDocContent" class="calc-input" style="min-height:80px; background:#1e293b; color:#fff; border-color:#475569; font-size:0.8rem;" placeholder="Pegá acá un protocolo o apunte para incorporarlo a la memoria de GLUC-IA..."></textarea>\n              <button class="nav-btn active" style="padding:9px; font-size:0.8rem;" onclick="guardarNuevoDocumentoRag()">\n                📥 Guardar en la Biblioteca del Curso\n              </button>\n              <div id="newRagDocStatus" style="font-size:0.76rem; color:#34d399; display:none;"></div>\n            </div>\n          </details>\n        </aside>\n\n        <!-- ESCENARIO DERECHO: CONVERSACIÓN CON GLUC-IA -->\n        <div class="surface-card" style="padding:20px;">\n          <div style="font-size:0.82rem; font-weight:800; color:#0f172a; margin-bottom:8px;">\n            ⚡ Consultas clínicas frecuentes (tocá un tema o escribí tu pregunta abajo):\n          </div>\n\n          <!-- CHIPS DE CONSULTAS ABIERTAS POR TEMA -->\n          <div style="display:flex; flex-wrap:wrap; gap:7px; margin-bottom:14px;">\n            <button class="quick-chip" onclick="presetQuery(\'¿Cuáles son los criterios diagnósticos de diabetes y prediabetes, cómo se hace la PTOG de 75 g y por qué no usar alcohol en el HGT?\')">\n              🔬 Diagnóstico, PTOG y Técnica HGT\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cómo diferencio el Fenómeno del Alba del Efecto Somogyi a las 03:00 AM y qué es el tiempo de retardo del sensor FreeStyle?\')">\n              📟 Sensores CGM y Alba vs Somogyi\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Por qué en el adulto mayor frágil la meta de HbA1c es menor a 8.0% y qué peligro tienen las sulfonilureas?\')">\n              🧓 Adulto Mayor Frágil y Metas DBT2\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cómo se diagnostica la Diabetes Gestacional en Argentina (SAD/MSAL), qué explica la Hipótesis de Pedersen y qué hago con la insulina tras el parto?\')">\n              🤰 Embarazo, Pedersen y Puerperio\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿En qué orden conviene comer el Método del Plato, cómo actúa el GLUT-4 en el ejercicio y por qué está prohibido ejercitarse con más de 250 mg/dL y cetonas?\')">\n              🏃\u200d♂️ Plato, GLUT-4 y Ejercicio Seguro\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cuál es el perfil de cada insulina, cómo se conserva la cadena de frío, cómo es la técnica FITTER de 4 mm y cómo se mezcla Corriente con NPH?\')">\n              💉 Insulinas, Frío, FITTER y Mezclas\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cuándo suspendo Metformina, Glibenclamida, Empagliflozina (iSGLT2) y Semaglutida (GLP-1) en internación, contraste o cirugía, y qué es la Cetoacidosis Euglucémica?\')">\n              💊 Orales, Gliflozinas (CAD Euglucémica) y Ozempic\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'Tengo un paciente de 75 kg en Cetoacidosis con glucemia de 410 mg/dL y potasio de 2.9 mEq/L: ¿puedo iniciar la bomba de insulina EV y cómo hago luego el pase a subcutánea?\')">\n              🚨 Caso Real: CAD + Potasio 2.9 + Bomba EV\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cómo diferencio un pie neuropático de un pie isquémico, cómo uso el monofilamento de 10 g y por qué está prohibido debridar una escara negra seca sin pulsos?\')">\n              🦶 Pie Neuropático vs Isquémico y Escara Seca\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Qué hago si un paciente recibe corticoides (Prednisona/Dexametasona) o si se tapa la sonda de alimentación enteral en un paciente con insulina?\')">\n              🏥 Corticoides y Sonda Nasogástrica\n            </button>\n            <button class="quick-chip" onclick="presetQuery(\'¿Cómo aplico el método Teach-Back con la lapicera antes del alta y qué significan las reglas de Días de Enfermedad y la sigla SADMANS?\')">\n              🎓 Alta Teach-Back y Regla SADMANS\n            </button>\n          </div>\n\n          <!-- CAJA DE ENTRADA DE PREGUNTA ABIERTA -->\n          <div style="display:flex; gap:10px; align-items:stretch;">\n            <textarea id="copilotoInput" class="calc-input" style="min-height:68px; flex:1; font-size:0.92rem;" placeholder="Escribí tu consulta clínica para GLUC-IA (ej: \'¿Por qué no se da chocolate en una hipoglucemia?\' o \'Tomame una pregunta de examen de la Unidad 7\')..."></textarea>\n            <button class="nav-btn active" style="padding:0 24px; font-weight:800; font-size:0.92rem;" onclick="enviarConsultaCopiloto()">\n              Consultar a GLUC-IA ✨\n            </button>\n          </div>\n\n          <!-- RESPUESTA INTERACTIVA DE GLUC-IA -->\n          <div id="copilotoOutput" class="ai-response-box" style="display:block; margin-top:16px; min-height:220px;">\n            <div style="color:#94a3b8; font-size:0.88rem;">\n              👋 <strong>¡Hola! Soy GLUC-IA, el Tutor Clínico Virtual del Laboratorio de Estudio de Diabetes para Enfermería — Dr. Marcos Gamond.</strong><br><br>\n              Estoy entrenado con las <strong>10 Unidades del programa (60 hs)</strong> y las guías oficiales <strong>ADA 2025/2026, Sociedad Argentina de Diabetes (SAD), MSAL Argentina, Consenso FITTER e IWGDF Pie Diabético</strong>.<br>\n              • Escribí cualquier consulta de guardia, internación o consultorio, o seleccioná un módulo a la izquierda para profundizar en una clase específica.\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n  </main>\n\n  <!-- MODAL DE DICCIONARIO CLÍNICO DE SIGLAS Y ABREVIATURAS EN DIABETES (A-Z) -->\n  <div id="modalGlosarioSiglas" class="siglas-modal-backdrop" style="display:none;" onclick="if(event.target===this) cerrarModalGlosarioSiglas()">\n    <div class="siglas-modal-card">\n      <div style="display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap; border-bottom:1.5px solid #e2e8f0; padding-bottom:12px;">\n        <div>\n          <span class="tag-sigla" style="background:#e0f2fe; color:#0369a1; margin-bottom:2px;">📖 GLOSARIO OFICIAL DEL CURSO • DR. MARCOS GAMOND</span>\n          <h3 style="font-size:1.2rem; font-weight:800; color:#0f172a; margin:0;">Diccionario de Siglas y Abreviaturas en Diabetes para Enfermería</h3>\n        </div>\n        <div style="display:flex; gap:8px;">\n          <button class="quick-chip" style="background:#dcfce7; color:#166534; border-color:#86efac; font-weight:800;" onclick="imprimirGlosarioSiglasCompleto()">🖨️ Imprimir Glosario</button>\n          <button class="quick-chip" style="background:#fee2e2; color:#991b1b; border-color:#fca5a5; font-weight:800;" onclick="cerrarModalGlosarioSiglas()">✖ Cerrar</button>\n        </div>\n      </div>\n\n      <div style="margin:12px 0; display:flex; gap:10px; flex-wrap:wrap;">\n        <input type="text" id="inputBuscarSigla" class="calc-input" style="flex:1; min-width:220px;" placeholder="🔍 Buscar sigla o término (ej: PTOG, HGT, HbA1c, TIR, CAD, EHH, SADMANS, NPO)..." oninput="filtrarGlosarioSiglas()" />\n        <select id="selectFiltroUnidadSigla" class="calc-input" style="width:auto; min-width:190px;" onchange="filtrarGlosarioSiglas()">\n          <option value="todas">📚 Todas las Unidades (1 a 10)</option>\n          <option value="1">Unidad 1 (Fisiopatología / Incretinas)</option>\n          <option value="2">Unidad 2 (Diagnóstico / PTOG / HbA1c)</option>\n          <option value="3">Unidad 3 (Metas / HGT / MCG / TIR)</option>\n          <option value="4">Unidad 4 (Embarazo / Gestacional)</option>\n          <option value="5">Unidad 5 (Nutrición / GLUT-4 / Ejercicio)</option>\n          <option value="6">Unidad 6 (Insulinas / Cadena Frío / FITTER)</option>\n          <option value="7">Unidad 7 (Antidiabéticos Orales / iSGLT2 / GLP-1)</option>\n          <option value="8">Unidad 8 (Hipoglucemia / CAD / EHH / Bomba EV)</option>\n          <option value="9">Unidad 9 (Pie Diabético / IWGDF / SINBAD)</option>\n          <option value="10">Unidad 10 (Educación Teach-Back / SADMANS / Alta)</option>\n        </select>\n      </div>\n\n      <div id="glosarioSiglasModalList" class="siglas-modal-grid"></div>\n    </div>\n  </div>\n\n  <script src="/static/js/diaguias.js?v=5.7"></script>\n</body>\n</html>\n'
CSS_CONTENT = "/* ============================================================================\n   DIAGUÍAS IA — CAMPUS ASINCRÓNICO DE 10 UNIDADES & COPILOTO EN DIABETOLOGÍA\n   Diseño Limpio, Guiado y Comercializable (LMS + Evidencia + Autoevaluación)\n   ============================================================================ */\n:root {\n  --bg-page: #f1f5f9;\n  --bg-surface: #ffffff;\n  --bg-subtle: #f8fafc;\n  --navy-header: #0f172a;\n  --primary-blue: #0284c7;\n  --primary-dark: #0369a1;\n  --emerald: #059669;\n  --amber: #d97706;\n  --crimson: #e11d48;\n  --text-dark: #0f172a;\n  --text-secondary: #475569;\n  --border-color: #e2e8f0;\n  --radius-lg: 16px;\n  --radius-md: 12px;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\n  background: var(--bg-page);\n  color: var(--text-dark);\n  line-height: 1.55;\n  min-height: 100vh;\n}\n\n/* HEADER INSTITUCIONAL CON ESCUDO ACADÉMICO */\n.header-bar {\n  background: linear-gradient(135deg, #091326 0%, #0f2557 52%, #0c4a6e 100%);\n  border-bottom: 2px solid rgba(56, 189, 248, 0.35);\n  color: #fff;\n  padding: 12px 26px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 16px;\n  box-shadow: 0 8px 26px rgba(15, 23, 42, 0.22);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.brand-box {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.brand-emblem-img {\n  width: 54px;\n  height: 54px;\n  border-radius: 14px;\n  object-fit: contain;\n  border: 2px solid #38bdf8;\n  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.35);\n  background: #ffffff;\n  flex-shrink: 0;\n}\n\n.brand-text-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.brand-eyebrow {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.68rem;\n  font-weight: 800;\n  letter-spacing: 0.07em;\n  color: #fde68a;\n  text-transform: uppercase;\n}\n\n.brand-dot {\n  color: #38bdf8;\n}\n\n.brand-box h1 {\n  font-size: 1.18rem;\n  font-weight: 800;\n  letter-spacing: -0.01em;\n  color: #ffffff;\n  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);\n  line-height: 1.2;\n}\n\n.brand-box p {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  font-size: 0.76rem;\n  color: #bae6fd;\n  font-weight: 600;\n  margin-top: 2px;\n}\n\n.director-pill {\n  background: rgba(251, 191, 36, 0.16);\n  border: 1px solid rgba(251, 191, 36, 0.45);\n  color: #fef08a;\n  padding: 2px 9px;\n  border-radius: 999px;\n  font-weight: 700;\n  font-size: 0.74rem;\n}\n\n.brand-sub-guia {\n  color: #7dd3fc;\n  font-size: 0.73rem;\n}\n\n/* BARRA DE PROGRESO ASINCRÓNICO EN HEADER */\n.progress-pill {\n  background: rgba(255, 255, 255, 0.1);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  padding: 8px 14px;\n  border-radius: 12px;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.progress-track {\n  width: 110px;\n  height: 8px;\n  background: rgba(255, 255, 255, 0.2);\n  border-radius: 999px;\n  overflow: hidden;\n}\n\n.progress-fill {\n  height: 100%;\n  background: #34d399;\n  width: 0%;\n  transition: width 0.35s ease;\n}\n\n/* PESTAÑAS DE NAVEGACIÓN PRINCIPAL */\n.nav-pills {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.nav-btn {\n  background: rgba(255, 255, 255, 0.1);\n  color: #e2e8f0;\n  border: 1px solid rgba(255, 255, 255, 0.18);\n  padding: 9px 15px;\n  border-radius: 999px;\n  font-size: 0.82rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: all 0.2s;\n}\n\n.nav-btn:hover {\n  background: rgba(255, 255, 255, 0.2);\n  color: #fff;\n}\n\n.nav-btn.active {\n  background: #38bdf8;\n  color: #0f172a;\n  border-color: #38bdf8;\n  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.4);\n}\n\n/* CONTENEDOR PRINCIPAL */\n.workspace {\n  max-width: 1380px;\n  margin: 0 auto;\n  padding: 24px 22px 60px;\n}\n\n.view-pane {\n  display: none;\n  animation: slideUp 0.22s ease;\n}\n\n.view-pane.active {\n  display: block;\n}\n\n@keyframes slideUp {\n  from { opacity: 0; transform: translateY(5px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n/* LAYOUT DEL CAMPUS ASINCRÓNICO (SIDEBAR 10 UNIDADES + AULA ACTIVA) */\n.campus-layout {\n  display: grid;\n  grid-template-columns: 335px 1fr;\n  gap: 22px;\n  align-items: start;\n}\n\n@media (max-width: 1024px) {\n  .campus-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n.units-sidebar {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 16px;\n  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);\n}\n\n.unit-nav-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 11px 13px;\n  border-radius: 11px;\n  border: 1.5px solid transparent;\n  cursor: pointer;\n  transition: all 0.18s;\n  margin-bottom: 6px;\n  background: var(--bg-subtle);\n}\n\n.unit-nav-item:hover {\n  border-color: #cbd5e1;\n  background: #f0f9ff;\n}\n\n.unit-nav-item.active {\n  border-color: var(--primary-blue);\n  background: #e0f2fe;\n}\n\n.unit-status-badge {\n  font-size: 0.72rem;\n  font-weight: 800;\n  padding: 3px 8px;\n  border-radius: 999px;\n  white-space: nowrap;\n}\n\n.unit-status-badge.done {\n  background: #dcfce7;\n  color: #15803d;\n}\n\n.unit-status-badge.pending {\n  background: #e2e8f0;\n  color: #475569;\n}\n\n/* PANEL CENTRAL DE LA UNIDAD */\n.unit-stage {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 26px;\n  box-shadow: 0 6px 22px rgba(15, 23, 42, 0.05);\n}\n\n.unit-header-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 14px;\n  flex-wrap: wrap;\n  padding-bottom: 16px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n/* SUB-PESTAÑAS INTERNAS DE CADA UNIDAD (4 PASOS PEDAGÓGICOS) */\n.unit-subtabs {\n  display: flex;\n  gap: 8px;\n  margin: 18px 0 20px;\n  flex-wrap: wrap;\n  border-bottom: 2px solid #f1f5f9;\n  padding-bottom: 12px;\n}\n\n.subtab-btn {\n  background: #f1f5f9;\n  color: #334155;\n  border: 1.5px solid #cbd5e1;\n  padding: 9px 16px;\n  border-radius: 10px;\n  font-size: 0.84rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: all 0.18s;\n}\n\n.subtab-btn:hover {\n  background: #e0f2fe;\n  border-color: var(--primary-blue);\n}\n\n.subtab-btn.active {\n  background: var(--primary-blue);\n  color: #fff;\n  border-color: var(--primary-blue);\n}\n\n/* TARJETAS DE TEORÍA Y FISIOPATOLOGÍA */\n.theory-card {\n  background: #f8fafc;\n  border: 1px solid var(--border-color);\n  border-left: 4px solid var(--primary-blue);\n  border-radius: 12px;\n  padding: 16px 18px;\n  margin-bottom: 14px;\n}\n\n.theory-card h4 {\n  font-size: 1rem;\n  color: #0f172a;\n  margin-bottom: 6px;\n}\n\n.theory-card p {\n  font-size: 0.92rem;\n  color: #334155;\n}\n\n/* TABLA DE GUÍAS Y CONSENSOS */\n.consensus-table {\n  width: 100%;\n  border-collapse: collapse;\n  margin-top: 12px;\n  font-size: 0.87rem;\n}\n\n.consensus-table th {\n  background: #0f172a;\n  color: #fff;\n  text-align: left;\n  padding: 11px 14px;\n}\n\n.consensus-table td {\n  padding: 11px 14px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.consensus-table tr:nth-child(even) {\n  background: #f8fafc;\n}\n\n/* SISTEMA DE AUTOEVALUACIÓN (QUIZ POR UNIDAD) */\n.quiz-question-card {\n  background: #f8fafc;\n  border: 1.5px solid var(--border-color);\n  border-radius: 14px;\n  padding: 18px;\n  margin-bottom: 16px;\n}\n\n.quiz-option-label {\n  display: block;\n  background: #fff;\n  border: 1.5px solid #cbd5e1;\n  border-radius: 10px;\n  padding: 11px 14px;\n  margin-top: 8px;\n  cursor: pointer;\n  font-size: 0.9rem;\n  font-weight: 600;\n  transition: all 0.15s;\n}\n\n.quiz-option-label:hover {\n  background: #f0f9ff;\n  border-color: var(--primary-blue);\n}\n\n.quiz-explanation {\n  margin-top: 10px;\n  padding: 12px;\n  border-radius: 10px;\n  font-size: 0.86rem;\n  display: none;\n}\n\n/* ELEMENTOS GENERALES */\n.section-banner {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-left: 5px solid var(--primary-blue);\n  border-radius: var(--radius-lg);\n  padding: 18px 22px;\n  margin-bottom: 22px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 14px;\n}\n\n.grid-2col {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 22px;\n  align-items: start;\n}\n\n@media (max-width: 960px) {\n  .grid-2col {\n    grid-template-columns: 1fr;\n  }\n}\n\n.surface-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 22px;\n  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);\n}\n\n.tag-sigla {\n  display: inline-block;\n  font-size: 0.72rem;\n  font-weight: 800;\n  padding: 3px 10px;\n  border-radius: 999px;\n  background: #e0f2fe;\n  color: #0369a1;\n  margin-bottom: 6px;\n}\n\n.gold-rule-box {\n  background: #fffbeb;\n  border: 1.5px solid #fcd34d;\n  border-radius: 12px;\n  padding: 15px 18px;\n  margin: 16px 0;\n  color: #92400e;\n  font-size: 0.9rem;\n}\n\n.algo-step-box {\n  background: #f0f9ff;\n  border: 2px solid #7dd3fc;\n  border-radius: 14px;\n  padding: 20px;\n  margin-top: 12px;\n}\n\n.algo-option-btn {\n  width: 100%;\n  text-align: left;\n  background: #ffffff;\n  border: 1.5px solid #cbd5e1;\n  padding: 14px 16px;\n  border-radius: 12px;\n  font-size: 0.92rem;\n  font-weight: 700;\n  color: var(--text-dark);\n  cursor: pointer;\n  margin-top: 10px;\n  transition: all 0.18s;\n}\n\n.algo-option-btn:hover {\n  border-color: var(--primary-blue);\n  background: #e0f2fe;\n}\n\n.calc-group {\n  margin-bottom: 14px;\n}\n\n.calc-group label {\n  display: block;\n  font-size: 0.82rem;\n  font-weight: 700;\n  color: var(--text-secondary);\n  margin-bottom: 5px;\n}\n\n.calc-input {\n  width: 100%;\n  padding: 10px 14px;\n  border: 1.5px solid #cbd5e1;\n  border-radius: 10px;\n  font-size: 0.95rem;\n  font-family: inherit;\n}\n\n.calc-result {\n  margin-top: 16px;\n  padding: 16px;\n  border-radius: 12px;\n  background: #ecfdf5;\n  border: 1.5px solid #6ee7b7;\n  color: #065f46;\n  font-size: 0.9rem;\n}\n\n.quick-chip {\n  background: #f1f5f9;\n  border: 1px solid #cbd5e1;\n  color: #1e293b;\n  padding: 8px 13px;\n  border-radius: 999px;\n  font-size: 0.8rem;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.quick-chip:hover {\n  background: #e0f2fe;\n  border-color: var(--primary-blue);\n}\n\n.ai-response-box {\n  background: #0f172a;\n  color: #f8fafc;\n  border-radius: 14px;\n  padding: 20px;\n  margin-top: 16px;\n  font-size: 0.92rem;\n  line-height: 1.65;\n}\n\n/* AYUDAS VISUALES LIMPIAS (MAPA VISUAL DE 4 NODOS + BANNER FOTOGRÁFICO) */\n.visual-strip-4 {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 12px;\n  margin: 16px 0 20px;\n}\n\n@media (max-width: 900px) {\n  .visual-strip-4 {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n.visual-node-card {\n  background: linear-gradient(180deg, #ffffff 0%, #f0f9ff 100%);\n  border: 1.5px solid #bae6fd;\n  border-top: 4px solid #0284c7;\n  border-radius: 14px;\n  padding: 14px;\n  position: relative;\n  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.06);\n  transition: transform 0.2s, box-shadow 0.2s;\n}\n\n.visual-node-card:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 8px 18px rgba(2, 132, 199, 0.14);\n}\n\n.visual-node-icon {\n  width: 38px;\n  height: 38px;\n  border-radius: 10px;\n  background: #e0f2fe;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.25rem;\n  margin-bottom: 8px;\n}\n\n.visual-node-title {\n  font-size: 0.86rem;\n  font-weight: 800;\n  color: #0f172a;\n  margin-bottom: 4px;\n}\n\n.visual-node-desc {\n  font-size: 0.79rem;\n  color: #334155;\n  line-height: 1.38;\n}\n\n/* TARJETA DE TÍTULO DE UNIDAD CON MINI-IMAGEN COMPACTA + SEMÁFORO CLÍNICO */\n.unit-header-card {\n  background: linear-gradient(135deg, #f8fafc 0%, #f0f9ff 100%);\n  border: 1.5px solid #bae6fd;\n  border-left: 5px solid #0284c7;\n  border-radius: 16px;\n  padding: 16px 18px;\n  box-shadow: 0 4px 16px rgba(2, 132, 199, 0.06);\n}\n\n.unit-header-main {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n@media (max-width: 680px) {\n  .unit-header-main {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n}\n\n.unit-mini-thumb {\n  width: 92px;\n  height: 92px;\n  object-fit: cover;\n  border-radius: 14px;\n  border: 2px solid #0284c7;\n  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.14);\n  flex-shrink: 0;\n}\n\n.unit-title-content {\n  flex: 1;\n  min-width: 0;\n}\n\n.unit-main-heading {\n  font-size: 1.32rem;\n  font-weight: 800;\n  color: #0f172a;\n  line-height: 1.25;\n  margin-top: 2px;\n}\n\n.unit-main-subtitle {\n  font-size: 0.89rem;\n  color: #334155;\n  margin-top: 4px;\n  line-height: 1.45;\n}\n\n.unit-traffic-strip {\n  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);\n  border-radius: 12px;\n  padding: 10px 12px;\n  margin-top: 12px;\n  color: #fff;\n}\n\n.traffic-meters {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 10px;\n}\n\n@media (max-width: 780px) {\n  .traffic-meters {\n    grid-template-columns: 1fr;\n  }\n}\n\n.traffic-pill {\n  border-radius: 10px;\n  padding: 8px 11px;\n  font-size: 0.78rem;\n}\n\n.traffic-pill.green {\n  background: rgba(16, 185, 129, 0.16);\n  border: 1px solid rgba(16, 185, 129, 0.45);\n  color: #a7f3d0;\n}\n\n.traffic-pill.amber {\n  background: rgba(245, 158, 11, 0.16);\n  border: 1px solid rgba(245, 158, 11, 0.45);\n  color: #fde68a;\n}\n\n.traffic-pill.red {\n  background: rgba(244, 63, 94, 0.18);\n  border: 1px solid rgba(244, 63, 94, 0.5);\n  color: #fecdd3;\n}\n\n/* BARRA DE SIGLAS Y ABREVIATURAS DE CADA UNIDAD */\n.unit-siglas-box {\n  background: #ffffff;\n  border: 1.5px dashed #7dd3fc;\n  border-radius: 12px;\n  padding: 10px 13px;\n  margin-top: 10px;\n}\n\n.unit-siglas-pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n}\n\n.sigla-chip-item {\n  background: #f0f9ff;\n  border: 1px solid #bae6fd;\n  border-radius: 8px;\n  padding: 4px 10px;\n  font-size: 0.78rem;\n  color: #334155;\n  line-height: 1.35;\n}\n\n.sigla-chip-item strong {\n  color: #0369a1;\n  font-weight: 800;\n}\n\n/* MODAL DEL DICCIONARIO DE SIGLAS Y ABREVIATURAS */\n.siglas-modal-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.68);\n  backdrop-filter: blur(3px);\n  z-index: 9999;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.siglas-modal-card {\n  background: #ffffff;\n  border-radius: 18px;\n  max-width: 980px;\n  width: 100%;\n  max-height: 86vh;\n  display: flex;\n  flex-direction: column;\n  padding: 22px;\n  box-shadow: 0 20px 50px rgba(15, 23, 42, 0.35);\n}\n\n.siglas-modal-grid {\n  overflow-y: auto;\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 10px;\n  padding-right: 6px;\n}\n\n@media (max-width: 720px) {\n  .siglas-modal-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.sigla-dict-card {\n  background: #f8fafc;\n  border: 1px solid #cbd5e1;\n  border-left: 4px solid #0284c7;\n  border-radius: 10px;\n  padding: 10px 13px;\n}\n\n.sigla-dict-card .sigla-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 3px;\n}\n\n.sigla-dict-card .sigla-code {\n  font-size: 0.94rem;\n  font-weight: 800;\n  color: #0369a1;\n}\n\n.sigla-dict-card .sigla-unit-badge {\n  font-size: 0.68rem;\n  font-weight: 800;\n  background: #e0f2fe;\n  color: #0284c7;\n  padding: 2px 7px;\n  border-radius: 999px;\n}\n\n.sigla-dict-card .sigla-full {\n  font-size: 0.84rem;\n  font-weight: 700;\n  color: #0f172a;\n}\n\n.sigla-dict-card .sigla-desc {\n  font-size: 0.78rem;\n  color: #475569;\n  margin-top: 2px;\n  line-height: 1.38;\n}\n\n/* IMPRESIÓN EN PÁGINA COMPLETA A4 (SIN BARRA LATERAL NI RECORTES) */\n@media print {\n  @page {\n    size: A4 portrait;\n    margin: 10mm;\n  }\n  body {\n    background: #ffffff !important;\n    color: #0f172a !important;\n    -webkit-print-color-adjust: exact !important;\n    print-color-adjust: exact !important;\n  }\n  .header-bar .nav-pills,\n  .header-bar .progress-pill,\n  .units-sidebar,\n  .unit-subtabs,\n  #viewUploadNLM {\n    display: none !important;\n  }\n  .workspace {\n    max-width: 100% !important;\n    padding: 0 !important;\n    margin: 0 !important;\n  }\n  .campus-layout,\n  .grid-2col {\n    display: block !important;\n    width: 100% !important;\n  }\n  .unit-stage {\n    width: 100% !important;\n    box-shadow: none !important;\n    border: none !important;\n    padding: 0 !important;\n  }\n  #viewInfografia {\n    display: block !important;\n    width: 100% !important;\n    page-break-inside: avoid;\n    margin-bottom: 16px;\n  }\n  #uploadedInfografiaImg {\n    width: 100% !important;\n    max-height: 240mm !important;\n    object-fit: contain !important;\n  }\n}\n\n\n"
JS_CONTENT = '// ============================================================================\n// DIAGUÍAS IA — MOTOR FRONTEND v4.0 (PRESENTACIÓN + INFOGRAFÍA + NOTEBOOKLM)\n// ============================================================================\n\nlet UNIDADES = [];\nlet CONSENSOS = {};\nlet ALGORITMOS = {};\nlet currentUnitIdx = 0;\nlet currentSlideIdx = 0;\nlet currentAlgoId = "algo_hipoglucemia";\nconst STORAGE_KEY = "diaguias_unidades_aprobadas_v1";\n\nfunction getApprovedUnits() {\n  try {\n    return JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");\n  } catch (e) {\n    return {};\n  }\n}\n\nfunction saveApprovedUnit(unitId, scorePct) {\n  const data = getApprovedUnits();\n  data[unitId] = scorePct;\n  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));\n  updateGlobalProgressUI();\n}\n\nfunction resetearProgreso() {\n  localStorage.removeItem(STORAGE_KEY);\n  renderUnitsSidebar();\n  selectUnit(currentUnitIdx);\n  updateGlobalProgressUI();\n}\n\nfunction updateGlobalProgressUI() {\n  const approved = Object.keys(getApprovedUnits()).length;\n  const total = UNIDADES.length || 10;\n  const pct = Math.round((approved / total) * 100);\n  document.getElementById("globalProgressText").textContent = `${approved} / ${total} Unidades (${pct}%)`;\n  document.getElementById("globalProgressBar").style.width = `${pct}%`;\n}\n\nwindow.addEventListener("DOMContentLoaded", async () => {\n  try {\n    const [resProg, resCons] = await Promise.all([\n      window.__PRELOADED_PROGRAMA__\n        ? Promise.resolve(window.__PRELOADED_PROGRAMA__)\n        : fetch("/api/programa").then(r => r.json()),\n      window.__PRELOADED_CONSENSOS__\n        ? Promise.resolve(window.__PRELOADED_CONSENSOS__)\n        : fetch("/api/consensos").then(r => r.json())\n    ]);\n    UNIDADES = resProg.unidades;\n    CONSENSOS = resCons.consensos;\n    ALGORITMOS = resCons.algoritmos;\n\n    renderUnitsSidebar();\n    selectUnit(0);\n    updateGlobalProgressUI();\n\n    loadAlgorithm("algo_hipoglucemia");\n    calcularBombaEV();\n    calcularSinbad();\n  } catch (e) {\n    console.error("Error iniciando Campus DIAGUÍAS IA:", e);\n  }\n});\n\nfunction openTab(tabId, btn) {\n  detenerMicroClaseVoz();\n  document.querySelectorAll(".view-pane").forEach(p => p.classList.remove("active"));\n  document.querySelectorAll(".header-bar .nav-btn").forEach(b => b.classList.remove("active"));\n  document.getElementById(tabId).classList.add("active");\n  btn.classList.add("active");\n}\n\n// ============================================================================\n// 1. RENDERIZADO DEL CAMPUS ASINCRÓNICO DE 10 UNIDADES\n// ============================================================================\nfunction renderUnitsSidebar() {\n  const list = document.getElementById("unitsSidebarList");\n  list.innerHTML = "";\n  const approvedMap = getApprovedUnits();\n\n  UNIDADES.forEach((u, idx) => {\n    const isDone = approvedMap[u.id] !== undefined;\n    const item = document.createElement("div");\n    item.className = "unit-nav-item" + (idx === currentUnitIdx ? " active" : "");\n    item.innerHTML = `\n      <div style="display:flex; align-items:center; gap:9px;">\n        <span style="font-size:1.25rem;">${u.icono}</span>\n        <div>\n          <div style="font-size:0.72rem; font-weight:800; color:#0284c7;">UNIDAD ${u.numero}</div>\n          <div style="font-size:0.83rem; font-weight:700; color:#0f172a; line-height:1.25;">${u.titulo.replace(/^Unidad \\d+:\\s*/, "")}</div>\n        </div>\n      </div>\n      <span class="unit-status-badge ${isDone ? "done" : "pending"}">\n        ${isDone ? "✅ " + approvedMap[u.id] + "%" : "⏳ Cursar"}\n      </span>\n    `;\n    item.onclick = () => selectUnit(idx);\n    list.appendChild(item);\n  });\n}\n\nfunction selectUnit(idx) {\n  detenerMicroClaseVoz();\n  currentUnitIdx = idx;\n  currentSlideIdx = 0;\n  const u = UNIDADES[idx];\n  if (!u) return;\n\n  renderUnitsSidebar();\n\n  document.getElementById("unitModuloBadge").textContent = u.modulo;\n  document.getElementById("unitDuracionBadge").textContent = u.duracion;\n  document.getElementById("unitMainTitle").textContent = `${u.icono} ${u.titulo}`;\n  document.getElementById("unitMainResumen").textContent = u.resumen;\n\n  const approvedMap = getApprovedUnits();\n  const stamp = document.getElementById("unitApprovalStamp");\n  if (approvedMap[u.id] !== undefined) {\n    stamp.innerHTML = `<span class="unit-status-badge done" style="font-size:0.85rem; padding:6px 14px;">🏆 Unidad Aprobada (${approvedMap[u.id]}%)</span>`;\n  } else {\n    stamp.innerHTML = `<span class="unit-status-badge pending" style="font-size:0.82rem; padding:6px 12px;">📝 Autoevaluación Pendiente</span>`;\n  }\n\n  // PASO 1: Presentación 5 Diapositivas + Infografía + Podcast/Video + Lectura 3 Min\n  const mm = u.multimedia || {};\n  renderCurrentSlide();\n  renderInfografiaBuiltIn(mm);\n\n  // Poblar Ayuda Visual Superior (Foto Clínica + Semáforo + Mapa Visual de 4 Nodos)\n  const fotosPorUnidad = {\n    1: "/static/assets/paciente_internacion.jpg",\n    2: "/static/assets/insulina_lipodistrofia.jpg",\n    3: "/static/assets/paciente_internacion.jpg",\n    4: "/static/assets/paciente_internacion.jpg",\n    5: "/static/assets/atlas_insulinas.jpg",\n    6: "/static/assets/atlas_insulinas.jpg",\n    7: "/static/assets/antidiabeticos_orales.jpg",\n    8: "/static/assets/paciente_internacion.jpg",\n    9: "/static/assets/pie_diabetico.jpg",\n    10: "/static/assets/atlas_insulinas.jpg"\n  };\n  const heroImg = document.getElementById("unitHeroPhoto");\n  if (heroImg) {\n    const thumbUri = window.__UNIT_THUMBNAILS__ && window.__UNIT_THUMBNAILS__[u.numero];\n    heroImg.src = thumbUri || fotosPorUnidad[u.numero] || "/static/assets/paciente_internacion.jpg";\n  }\n\n  const filaBase = (u.guias_consenso && u.guias_consenso.metas_tabla && u.guias_consenso.metas_tabla[0]) || {};\n  const trafficBox = document.getElementById("unitTrafficMeters");\n  if (trafficBox) {\n    trafficBox.innerHTML = `\n      <div class="traffic-pill green">\n        <div style="font-weight:800; font-size:0.72rem;">🟢 ESTÁNDAR / META</div>\n        <div style="margin-top:3px; color:#fff; font-weight:700;">${filaBase.criterio || "Meta"}: ${filaBase.normal || "-"}</div>\n      </div>\n      <div class="traffic-pill amber">\n        <div style="font-weight:800; font-size:0.72rem;">🟡 ALERTA / PRECAUCIÓN</div>\n        <div style="margin-top:3px; color:#fff; font-weight:700;">${filaBase.prediabetes !== "-" ? filaBase.prediabetes : "Vigilar signos precoces"}</div>\n      </div>\n      <div class="traffic-pill red">\n        <div style="font-weight:800; font-size:0.72rem;">🔴 PUNTO CRÍTICO</div>\n        <div style="margin-top:3px; color:#fff; font-weight:700;">${filaBase.diabetes || "-"}</div>\n      </div>\n    `;\n  }\n\n  const strip4 = document.getElementById("unitVisualStrip4");\n  if (strip4) {\n    strip4.innerHTML = "";\n    (mm.infografia_pasos || []).forEach(p => {\n      const node = document.createElement("div");\n      node.className = "visual-node-card";\n      node.innerHTML = `\n        <div class="visual-node-icon">${p.icono}</div>\n        <div class="visual-node-title">${p.titulo}</div>\n        <div class="visual-node-desc">${p.detalle}</div>\n      `;\n      strip4.appendChild(node);\n    });\n  }\n\n  // Poblar Referencia Rápida de Siglas y Abreviaturas de la Unidad\n  if (typeof renderSiglasUnidadActual === "function") {\n    renderSiglasUnidadActual(u.numero);\n  }\n\n  document.getElementById("mediaDurationBadge").textContent = mm.duracion_video || "05:30 min";\n  document.getElementById("mediaTitleText").textContent = mm.titulo_microclase || u.titulo;\n  document.getElementById("mediaScriptText").textContent = mm.guion_clase_grabada || "";\n  const btnDl = document.getElementById("btnDownloadNotebookLM");\n  if (btnDl) btnDl.href = mm.archivo_notebooklm_url || "#";\n  const audioEl = document.getElementById("unitPodcastAudio");\n  if (audioEl) {\n    const aUrl = mm.audio_podcast_url || "";\n    audioEl.src = aUrl.startsWith("http") ? aUrl : (aUrl ? aUrl + "?t=" + Date.now() : "");\n  }\n  const cMsg = document.getElementById("copyFeedbackMsg");\n  if (cMsg) cMsg.style.display = "none";\n  const uMsg = document.getElementById("uploadStatusMsg");\n  if (uMsg) uMsg.style.display = "none";\n\n  // Verificar si ya hay archivos subidos por el docente\n  actualizarEstadoArchivosSubidos(mm);\n\n  const lecturaBox = document.getElementById("lectura3MinContainer");\n  lecturaBox.innerHTML = "";\n  (mm.lectura_3_minutos || []).forEach(punto => {\n    const div = document.createElement("div");\n    div.style.background = "#ffffff";\n    div.style.border = "1px solid #e2e8f0";\n    div.style.borderLeft = "4px solid #0284c7";\n    div.style.borderRadius = "10px";\n    div.style.padding = "11px 14px";\n    div.style.fontSize = "0.89rem";\n    div.innerHTML = punto.replace(/\\*\\*(.*?)\\*\\*/g, "<strong style=\'color:#0f172a;\'>$1</strong>");\n    lecturaBox.appendChild(div);\n  });\n  document.getElementById("mediaGoldRuleShort").textContent = u.guias_consenso.regla_enfermeria;\n\n  // Prellenar editor de reemplazo de textos (Paso 4)\n  const elLectura = document.getElementById("editLectura3Min");\n  const elRegla = document.getElementById("editReglaOro");\n  const elBiblio = document.getElementById("editBiblioExtra");\n  if (elLectura) elLectura.value = (mm.lectura_3_minutos || []).join("\\n");\n  if (elRegla) elRegla.value = u.guias_consenso.regla_enfermeria || "";\n  if (elBiblio) elBiblio.value = "";\n  const stTxt = document.getElementById("editTextStatusMsg");\n  if (stTxt) stTxt.style.display = "none";\n\n  // PASO 2: Fisiopatología y Clínica\n  const fisioBox = document.getElementById("unitFisioContainer");\n  fisioBox.innerHTML = "";\n  u.fisiopatologia_cards.forEach(c => {\n    const div = document.createElement("div");\n    div.className = "theory-card";\n    div.innerHTML = `<h4>${c.titulo}</h4><p>${c.contenido}</p>`;\n    fisioBox.appendChild(div);\n  });\n\n  // PASO 3: Guías y Consensos\n  document.getElementById("unitGuiaFuente").textContent = "📚 " + u.guias_consenso.fuente;\n  const tbody = document.getElementById("unitGuiaTablaBody");\n  tbody.innerHTML = "";\n  u.guias_consenso.metas_tabla.forEach(row => {\n    const tr = document.createElement("tr");\n    tr.innerHTML = `\n      <td><strong>${row.criterio}</strong></td>\n      <td>${row.normal}</td>\n      <td>${row.prediabetes}</td>\n      <td><strong style="color:#0369a1;">${row.diabetes}</strong></td>\n    `;\n    tbody.appendChild(tr);\n  });\n  document.getElementById("unitGuiaReglaOro").textContent = u.guias_consenso.regla_enfermeria;\n\n  // PASO 4: Caso Clínico\n  document.getElementById("unitCasoEscenario").textContent = u.caso_practico.escenario;\n  document.getElementById("unitCasoPregunta").textContent = "❓ " + u.caso_practico.pregunta;\n  document.getElementById("unitCasoResolucion").textContent = u.caso_practico.resolucion;\n  document.getElementById("unitCasoResolucionBox").style.display = "none";\n\n  // PASO 5: Autoevaluación\n  renderUnitQuiz(u);\n\n  const firstBtn = document.querySelectorAll(".unit-subtabs .subtab-btn")[0];\n  switchUnitStep("stepMedia", firstBtn);\n}\n\n// ============================================================================\n// SUB-VISTAS MULTIMEDIA (PRESENTACIÓN / INFOGRAFÍA / PODCAST / CARGA NOTEBOOKLM)\n// ============================================================================\nfunction switchMediaSubView(viewId) {\n  detenerMicroClaseVoz();\n  document.querySelectorAll(".media-subview").forEach(v => v.style.display = "none");\n  const target = document.getElementById(viewId);\n  if (target) {\n    target.style.display = viewId === "viewSlides" ? "flex" : "block";\n  }\n}\n\nfunction renderCurrentSlide() {\n  const u = UNIDADES[currentUnitIdx];\n  const slides = (u && u.multimedia && u.multimedia.slides_presentacion) || [];\n  if (!slides.length) return;\n\n  const s = slides[currentSlideIdx] || slides[0];\n  document.getElementById("slideCounterBadge").textContent = `DIAPOSITIVA ${s.slide} DE ${slides.length}`;\n  document.getElementById("slideTitleText").textContent = s.titulo;\n  document.getElementById("slideBodyText").textContent = s.cuerpo;\n}\n\nfunction changeSlide(delta) {\n  detenerMicroClaseVoz();\n  const u = UNIDADES[currentUnitIdx];\n  const slides = (u && u.multimedia && u.multimedia.slides_presentacion) || [];\n  if (!slides.length) return;\n  currentSlideIdx = (currentSlideIdx + delta + slides.length) % slides.length;\n  renderCurrentSlide();\n}\n\nfunction reproducirSlideActualVoz() {\n  if (!("speechSynthesis" in window)) return;\n  window.speechSynthesis.cancel();\n  const u = UNIDADES[currentUnitIdx];\n  const slides = (u && u.multimedia && u.multimedia.slides_presentacion) || [];\n  const s = slides[currentSlideIdx];\n  if (!s) return;\n\n  const utter = new SpeechSynthesisUtterance(`${s.titulo}. ${s.cuerpo}`);\n  utter.lang = "es-AR";\n  utter.rate = 1.02;\n  window.speechSynthesis.speak(utter);\n}\n\nfunction renderInfografiaBuiltIn(mm) {\n  const grid = document.getElementById("infografiaBuiltInGrid");\n  grid.innerHTML = "";\n  (mm.infografia_pasos || []).forEach(p => {\n    const card = document.createElement("div");\n    card.style.background = "rgba(255,255,255,0.07)";\n    card.style.border = "1px solid rgba(56,189,248,0.35)";\n    card.style.borderRadius = "12px";\n    card.style.padding = "14px";\n    card.innerHTML = `\n      <div style="font-size:1.5rem; margin-bottom:4px;">${p.icono}</div>\n      <div style="font-weight:800; font-size:0.92rem; color:#38bdf8;">${p.titulo}</div>\n      <div style="font-size:0.84rem; color:#e2e8f0; margin-top:4px;">${p.detalle}</div>\n    `;\n    grid.appendChild(card);\n  });\n}\n\nfunction autoDetectMediaType(inputEl) {\n  if (!inputEl.files || !inputEl.files[0]) return;\n  const name = inputEl.files[0].name.toLowerCase();\n  const sel = document.getElementById("uploadMediaType");\n  if (!sel) return;\n  if (name.endsWith(".mp4") || name.endsWith(".webm") || name.endsWith(".mov")) {\n    sel.value = "video";\n  } else if (name.endsWith(".mp3") || name.endsWith(".wav") || name.endsWith(".m4a") || name.endsWith(".ogg")) {\n    sel.value = "podcast";\n  } else if (name.endsWith(".png") || name.endsWith(".jpg") || name.endsWith(".jpeg") || name.endsWith(".webp")) {\n    sel.value = "infografia";\n  } else if (name.endsWith(".pdf")) {\n    sel.value = "presentacion";\n  }\n}\n\nfunction actualizarEstadoArchivosSubidos(mm) {\n  const est = (mm && mm.estado_archivos) || {};\n\n  // Badges de estado en la pestaña de carga\n  const badgesBox = document.getElementById("uploadedFilesBadgesBox");\n  if (badgesBox) {\n    badgesBox.innerHTML = `\n      <span class="tag-sigla" style="background:${est.tiene_video ? \'#10b981\' : \'#334155\'}; color:#fff;">\n        ${est.tiene_video ? \'🟢 Video .MP4 Cargado\' : \'⚪ Video: Sin cargar\'}\n      </span>\n      <span class="tag-sigla" style="background:${est.tiene_audio ? \'#10b981\' : \'#334155\'}; color:#fff;">\n        ${est.tiene_audio ? \'🟢 Podcast Cargado\' : \'⚪ Podcast: Sin cargar\'}\n      </span>\n      <span class="tag-sigla" style="background:${est.tiene_infografia ? \'#10b981\' : \'#334155\'}; color:#fff;">\n        ${est.tiene_infografia ? \'🟢 Infografía Cargada\' : \'⚪ Infografía: Sin cargar\'}\n      </span>\n      <span class="tag-sigla" style="background:${est.tiene_pdf ? \'#10b981\' : \'#334155\'}; color:#fff;">\n        ${est.tiene_pdf ? \'🟢 PDF Cargado\' : \'⚪ PDF: Sin cargar\'}\n      </span>\n    `;\n  }\n\n  // PDF subido\n  const pdfBanner = document.getElementById("uploadedPdfBanner");\n  if (est.tiene_pdf) {\n    pdfBanner.style.display = "block";\n    document.getElementById("uploadedPdfLink").href = mm.presentacion_pdf_url + "?t=" + Date.now();\n  } else {\n    pdfBanner.style.display = "none";\n  }\n\n  // Infografía imagen subida\n  const infoBox = document.getElementById("uploadedInfografiaBox");\n  if (est.tiene_infografia) {\n    infoBox.style.display = "block";\n    document.getElementById("uploadedInfografiaImg").src = mm.infografia_data_uri || (mm.infografia_img_url + "?t=" + Date.now());\n  } else {\n    infoBox.style.display = "none";\n  }\n\n  // Video subido (se muestra en el Banner Superior de la Unidad y en la pestaña Podcast/Video)\n  const topVidBanner = document.getElementById("topUnitVideoBanner");\n  const topVidPlayer = document.getElementById("topUnitVideoPlayer");\n  const vidBox = document.getElementById("videoPlayerContainer");\n  if (est.tiene_video && mm.video_clase_url) {\n    const vUrl = mm.video_clase_url.startsWith("http")\n      ? mm.video_clase_url\n      : (mm.video_clase_url + "?t=" + Date.now());\n    if (topVidBanner && topVidPlayer) {\n      topVidBanner.style.display = "block";\n      topVidPlayer.src = vUrl;\n    }\n    if (vidBox) {\n      vidBox.style.display = "block";\n      document.getElementById("unitVideoPlayer").src = vUrl;\n    }\n  } else {\n    if (topVidBanner && topVidPlayer) {\n      topVidBanner.style.display = "none";\n      topVidPlayer.removeAttribute("src");\n    }\n    if (vidBox) {\n      vidBox.style.display = "none";\n    }\n  }\n}\n\nasync function subirArchivoNotebookLM() {\n  const fileInput = document.getElementById("uploadMediaFile");\n  const statusMsg = document.getElementById("uploadStatusMsg");\n\n  if (!fileInput.files || !fileInput.files[0]) {\n    statusMsg.style.display = "block";\n    statusMsg.style.color = "#fde047";\n    statusMsg.textContent = "⚠️ Seleccioná primero un archivo desde tu computadora.";\n    return;\n  }\n\n  autoDetectMediaType(fileInput);\n  const mediaType = document.getElementById("uploadMediaType").value;\n\n  const u = UNIDADES[currentUnitIdx];\n  const formData = new FormData();\n  formData.append("unit_num", u.numero);\n  formData.append("media_type", mediaType);\n  formData.append("file", fileInput.files[0]);\n\n  statusMsg.style.display = "block";\n  statusMsg.style.color = "#7dd3fc";\n  statusMsg.textContent = "⏳ Subiendo archivo \'" + fileInput.files[0].name + "\' a la Unidad " + u.numero + " (aguardá unos segundos si es un video pesado)...";\n\n  try {\n    const res = await fetch("/api/upload_media", {\n      method: "POST",\n      body: formData\n    }).then(r => r.json());\n\n    if (res.ok) {\n      u.multimedia.estado_archivos = res.estado_archivos;\n      actualizarEstadoArchivosSubidos(u.multimedia);\n      if (res.media_type === "podcast" || mediaType === "podcast") {\n        document.getElementById("unitPodcastAudio").src = res.url + "?t=" + Date.now();\n      }\n      statusMsg.style.color = "#34d399";\n      statusMsg.textContent = "✅ ¡Listo! " + res.mensaje + ". ¡Ya está visible arriba en el reproductor principal de esta unidad!";\n    } else {\n      statusMsg.style.color = "#f87171";\n      statusMsg.textContent = "❌ Error al subir el archivo.";\n    }\n  } catch (err) {\n    statusMsg.style.color = "#f87171";\n    statusMsg.textContent = "❌ Error de conexión al subir el archivo: " + err.message;\n  }\n}\n\nasync function guardarTextoNotebookLM() {\n  const u = UNIDADES[currentUnitIdx];\n  const lineas = document.getElementById("editLectura3Min").value\n    .split("\\n")\n    .map(s => s.trim())\n    .filter(Boolean);\n  const regla = document.getElementById("editReglaOro").value.trim();\n  const biblio = document.getElementById("editBiblioExtra").value.trim();\n  const st = document.getElementById("editTextStatusMsg");\n\n  st.style.display = "block";\n  st.textContent = "⏳ Guardando cambios en la Unidad " + u.numero + "...";\n\n  const res = await fetch("/api/update_unit_content", {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify({\n      unit_id: u.id,\n      lectura_3_min_lineas: lineas,\n      regla_oro: regla,\n      bibliografia_extra_notebooklm: biblio\n    })\n  }).then(r => r.json());\n\n  if (res.ok) {\n    const resProg = await fetch("/api/programa").then(r => r.json());\n    UNIDADES = resProg.unidades;\n    selectUnit(currentUnitIdx);\n    switchMediaSubView("viewUploadNLM");\n    const stAfter = document.getElementById("editTextStatusMsg");\n    stAfter.style.display = "block";\n    stAfter.textContent = "✅ ¡Textos y bibliografía reemplazados con éxito!";\n  }\n}\n\nfunction reproducirMicroClaseVoz() {\n  if (!("speechSynthesis" in window)) {\n    alert("Tu navegador no soporta lectura de voz automática.");\n    return;\n  }\n  window.speechSynthesis.cancel();\n  const u = UNIDADES[currentUnitIdx];\n  const guion = (u && u.multimedia && u.multimedia.guion_clase_grabada) || "";\n  if (!guion) return;\n\n  const utter = new SpeechSynthesisUtterance(guion);\n  utter.lang = "es-AR";\n  utter.rate = 1.02;\n  window.speechSynthesis.speak(utter);\n}\n\nfunction detenerMicroClaseVoz() {\n  if ("speechSynthesis" in window) {\n    window.speechSynthesis.cancel();\n  }\n}\n\nconst PROMPTS_INFOGRAFIAS_UNIDADES = {\n  1: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 1 — FISIOPATOLOGÍA, CLASIFICACIÓN E INCRETINAS (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Islote Pancreático (Célula Beta/Insulina vs Alfa/Glucagón y GLUT-4), 2) Diferencias entre DBT1 (autoinmune/cetosis), DBT2 (insulinorresistencia), LADA y Gestacional, 3) Efecto Incretina (GLP-1 y GIP), y 4) REGLA SALVAVIDAS: Peligro de tratar LADA o DBT1 sin insulina basal.`,\n  2: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 2 — CRITERIOS DIAGNÓSTICOS, PTOG Y PRE-ANALÍTICA (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Los 4 Criterios Diagnósticos ADA/SAD (Ayunas ≥126, PTOG 2h ≥200, HbA1c ≥6.5%, Azar ≥200 mg/dL + 4 P), 2) Semáforo de Prediabetes (GAA 100-125, ITG 140-199, HbA1c 5.7-6.4%), 3) Técnica PTOG (75 g en 300 mL de agua en 5-10 min, reposo sentado sin fumar), y 4) REGLA SALVAVIDAS: Prohibido hacer PTOG si ayunas ≥126 mg/dL y causas que invalidan HbA1c.`,\n  3: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 3 — METAS GLUCÉMICAS, TÉCNICA HGT Y MONITOREO MCG (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Metas Ambulatorias (HbA1c <7%, ayunas 80-130, post <180) vs Internación (140-180 mg/dL), 2) Técnica HGT (agua y jabón sin alcohol en pulpejo, cara lateral, descartar 1ra gota, no ordeñar el dedo), 3) Monitoreo Continuo MCG (TIR >70% entre 70-180 mg/dL y lag time de 10-15 min), y 4) REGLA SALVAVIDAS: Prohibido HGT capilar en shock o vasopresores.`,\n  4: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 4 — DIABETES GESTACIONAL Y MANEJO PERIPARTO (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Tamizaje sem 24-28 (ALAD/SAD Argentina ≥100 ayunas o ≥140 a las 2h vs IADPSG 92/180/153), 2) Metas maternas (<95 ayunas, <140 1h, <120 2h) e insulina como elección, 3) Manejo intraparto (meta 70-110 mg/dL para evitar hipoglucemia neonatal), y 4) REGLA SALVAVIDAS: Bajar 50% o suspender insulina al alumbramiento placentario + lactancia precoz.`,\n  5: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 5 — NUTRICIÓN CLÍNICA, GLUT-4 Y EJERCICIO SEGURO (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Método del Plato ADA (50% vegetales sin almidón, 25% proteínas, 25% HC complejos; comer fibra y proteína primero), 2) Ejercicio y GLUT-4 por vía AMPK + riesgo de hipoglucemia nocturna tardía (24-48 h), 3) Semáforo pre-ejercicio (<100 colación 15-20 g HC; 100-250 seguro; >250 con cetonas o >300 prohibido), y 4) REGLA SALVAVIDAS: Peligro mortal de ejercitarse con >250 mg/dL y cetonas.`,\n  6: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 6 — INSULINAS, CADENA DE FRÍO Y TÉCNICA FITTER (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Farmacocinética (Ultrarrápidas 5-15 min; Corriente única apta EV; NPH turbia pico 4-10 h; Glargina/Degludec planas), 2) Cadena de frío (reserva 2-8 °C estante central, en uso <28-30 °C por 28 días, rolar NPH 20 veces sin agitar), 3) Técnica FITTER (aguja 4 mm a 90°, purgar 1-2 UI, contar 10 seg), y 4) REGLA SALVAVIDAS: No inyectar en lipohipertrofia y prohibido mezclar Glargina/Degludec.`,\n  7: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 7 — ANTIDIABÉTICOS ORALES, iSGLT2 Y GLP-1 (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Metformina (suspender 48 h antes de contraste iodado EV, TFG <30 o sepsis por acidosis láctica) y Sulfonilureas (suspender en ayuno NPO), 2) iDPP-4 y Linagliptina (elección en insuficiencia renal/diálisis sin ajuste), 3) iSGLT2 / Gliflozinas (suspender 3-4 días antes de cirugía), y 4) REGLA SALVAVIDAS: Cetoacidosis Euglucémica por iSGLT2 (<250 mg/dL) y broncoaspiración quirúrgica por GLP-1.`,\n  8: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 8 — COMPLICACIONES AGUDAS: HIPOGLUCEMIA, CAD Y EHH (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Hipoglucemia Nivel 1 (<70), Nivel 2 (<54) con Regla del 15 (15 g azúcar simple y HGT en 15 min, sin chocolate) y Nivel 3 inconsciente (prohibida vía oral: Dextrosa EV o Glucagón IM), 2) Secuencia CAD/EHH (1° SF 0.9%, 2° Potasio, 3° Bomba Insulina Corriente EV 100 UI en 100 mL SF a 0.1 UI/kg/h), 3) Dextrosa 5% en paralelo al bajar glucemia a 200-250 mg/dL, y 4) REGLA SALVAVIDAS: Frenar insulina si K+ <3.3 mEq/L y hacer overlap de 2-4 h antes de apagar la bomba EV.`,\n  9: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 9 — COMPLICACIONES CRÓNICAS Y PIE DIABÉTICO IWGDF (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Pie Neuropático (tibio, con pulsos, callo plantar, úlcera indolora) vs Pie Isquémico (frío, sin pulsos, úlcera dolorosa en dedos/talón), 2) Monofilamento 10 g (perpendicular 1.5 seg en \'C\' sin tocar callos) + Diapasón 128 Hz y escala SINBAD (≥3 derivar urgente), 3) Autocuidado (crema en talón y planta, NUNCA entre los dedos; prohibido bolsas de agua caliente), y 4) REGLA SALVAVIDAS: Prohibido cortar o debridar una escara negra y seca en pie isquémico sin pulsos.`,\n  10: `INSTRUCCIÓN DE TÍTULO OBLIGATORIO: Colocá como título principal y nombre de la infografía "UNIDAD 10 — EDUCACIÓN TEACH-BACK, DÍAS DE ENFERMEDAD Y SADMANS (Dr. Marcos Gamond)" bien grande arriba para identificarla fácil. Diseñá una INFOGRAFÍA CLÍNICA DE PÁGINA COMPLETA con 4 bloques: 1) Método Teach-Back (Demostración Inversa: que el paciente arme la lapicera, purgue 2 UI y retire el 2° capuchón interno), 2) Reglas de Días de Enfermedad (fiebre/vómitos: NUNCA suspender insulina basal, hidratar cada hora y medir HGT/cetonas cada 3-4 h), 3) Acrónimo SADMANS a pausar en deshidratación (Sulfonilureas, IECA, Diuréticos, Metformina, ARA-II, AINEs, SGLT2), y 4) Checklist de Supervivencia al Alta con insumos en mano.`\n};\n\nfunction copiarPromptNotebookLM() {\n  const u = UNIDADES[currentUnitIdx];\n  const prompt = (u && u.multimedia && u.multimedia.prompt_notebooklm) || "";\n  navigator.clipboard.writeText(prompt);\n  const msg = document.getElementById("copyFeedbackMsg");\n  msg.style.display = "block";\n  msg.textContent = "✅ ¡Prompt copiado! Subí el archivo .MD descargado a NotebookLM y pegá este prompt en «Personalizar Resumen de Audio o Video».";\n}\n\nfunction copiarPromptInfografiaUnidad() {\n  const u = UNIDADES[currentUnitIdx];\n  if (!u) return;\n  const prompt = PROMPTS_INFOGRAFIAS_UNIDADES[u.numero] || "";\n  navigator.clipboard.writeText(prompt);\n  const msg = document.getElementById("copyInfografiaFeedbackMsg");\n  if (msg) {\n    msg.style.display = "block";\n    msg.textContent = `✅ ¡Prompt de Infografía de la Unidad ${u.numero} copiado al portapapeles! Pegalo en NotebookLM, Gemini o Canva.`;\n  }\n}\n\nfunction imprimirInfografiaCompleta() {\n  const u = UNIDADES[currentUnitIdx];\n  if (!u) return;\n  const mm = u.multimedia || {};\n  const est = mm.estado_archivos || {};\n  const tieneImg = Boolean(est.tiene_infografia && (mm.infografia_data_uri || mm.infografia_img_url));\n  const imgUrl = tieneImg ? (mm.infografia_data_uri || (window.location.origin + mm.infografia_img_url + "?t=" + Date.now())) : "";\n\n  const pasosHtml = (mm.infografia_pasos || []).map(p => `\n    <div class="node-box">\n      <div class="node-title">${p.icono} ${p.titulo}</div>\n      <div class="node-desc">${p.detalle}</div>\n    </div>\n  `).join("");\n\n  const lecturaHtml = (mm.lectura_3_minutos || []).map(l => {\n    const formatted = l.replace(/\\*\\*(.*?)\\*\\*/g, "<strong>$1</strong>");\n    return `<li>${formatted}</li>`;\n  }).join("");\n\n  const filasTablaHtml = ((u.guias_consenso && u.guias_consenso.metas_tabla) || []).map(r => `\n    <tr>\n      <td><strong>${r.criterio}</strong></td>\n      <td>${r.normal}</td>\n      <td>${r.prediabetes}</td>\n      <td><strong>${r.diabetes}</strong></td>\n    </tr>\n  `).join("");\n\n  const printWin = window.open("", "_blank", "width=1050,height=900");\n  if (!printWin) {\n    window.print();\n    return;\n  }\n\n  printWin.document.write(`<!DOCTYPE html>\n<html lang="es">\n<head>\n  <meta charset="UTF-8" />\n  <title>Infografía Completa — ${u.titulo} — Dr. Marcos Gamond</title>\n  <style>\n    @page {\n      size: A4 portrait;\n      margin: 10mm;\n    }\n    * {\n      box-sizing: border-box;\n      -webkit-print-color-adjust: exact !important;\n      print-color-adjust: exact !important;\n    }\n    body {\n      font-family: \'Segoe UI\', Arial, sans-serif;\n      color: #0f172a;\n      background: #ffffff;\n      margin: 0;\n      padding: 0;\n    }\n    .page-sheet {\n      width: 100%;\n      page-break-after: always;\n    }\n    .page-sheet:last-child {\n      page-break-after: auto;\n    }\n    .header-banner {\n      background: linear-gradient(135deg, #0f172a, #1e3a8a);\n      color: #ffffff;\n      padding: 14px 18px;\n      border-radius: 12px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 12px;\n    }\n    .header-banner h1 {\n      font-size: 15px;\n      margin: 0;\n      letter-spacing: 0.02em;\n    }\n    .header-banner p {\n      font-size: 11.5px;\n      margin: 3px 0 0;\n      color: #bae6fd;\n    }\n    .unit-title-bar {\n      background: #f0f9ff;\n      border-left: 5px solid #0284c7;\n      padding: 10px 14px;\n      border-radius: 8px;\n      margin-bottom: 12px;\n    }\n    .unit-title-bar h2 {\n      font-size: 16px;\n      margin: 0;\n      color: #0f172a;\n    }\n    .unit-title-bar p {\n      font-size: 11.5px;\n      margin: 3px 0 0;\n      color: #334155;\n    }\n    .full-img-wrapper {\n      width: 100%;\n      text-align: center;\n      margin: 6px 0 12px;\n    }\n    .full-img-wrapper img {\n      width: 100%;\n      max-height: 235mm;\n      object-fit: contain;\n      border-radius: 10px;\n      border: 2px solid #0284c7;\n    }\n    .grid-4 {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 8px;\n      margin-bottom: 12px;\n    }\n    .node-box {\n      background: #f8fafc;\n      border: 1.5px solid #bae6fd;\n      border-top: 4px solid #0284c7;\n      border-radius: 8px;\n      padding: 9px 11px;\n    }\n    .node-title {\n      font-size: 12.5px;\n      font-weight: 800;\n      color: #0f172a;\n      margin-bottom: 3px;\n    }\n    .node-desc {\n      font-size: 11.5px;\n      color: #334155;\n      line-height: 1.35;\n    }\n    .section-box {\n      border: 1px solid #cbd5e1;\n      border-radius: 8px;\n      padding: 10px 14px;\n      margin-bottom: 10px;\n    }\n    .section-box h3 {\n      font-size: 13px;\n      margin: 0 0 6px;\n      color: #0369a1;\n      text-transform: uppercase;\n    }\n    .section-box ul {\n      margin: 0;\n      padding-left: 18px;\n      font-size: 11.3px;\n      line-height: 1.42;\n    }\n    .section-box li {\n      margin-bottom: 4px;\n    }\n    .gold-rule {\n      background: #fffbeb;\n      border: 2px solid #f59e0b;\n      border-radius: 8px;\n      padding: 10px 13px;\n      margin-bottom: 10px;\n      font-size: 11.3px;\n      line-height: 1.42;\n      color: #78350f;\n    }\n    .gold-rule strong {\n      color: #92400e;\n    }\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 10.8px;\n      margin-top: 4px;\n    }\n    th {\n      background: #0f172a;\n      color: #ffffff;\n      text-align: left;\n      padding: 6px 8px;\n    }\n    td {\n      border: 1px solid #cbd5e1;\n      padding: 6px 8px;\n      vertical-align: top;\n    }\n    tr:nth-child(even) {\n      background: #f8fafc;\n    }\n    .no-print-bar {\n      background: #0f172a;\n      color: #fff;\n      padding: 10px 18px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 14px;\n      border-radius: 8px;\n    }\n    .btn-print {\n      background: #10b981;\n      color: #052e16;\n      border: none;\n      padding: 8px 16px;\n      border-radius: 6px;\n      font-weight: 800;\n      cursor: pointer;\n      font-size: 13px;\n    }\n    @media print {\n      .no-print-bar {\n        display: none !important;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class="no-print-bar">\n    <div><strong>🖨️ Vista Previa de Impresión en Página Completa A4</strong> — ${u.titulo}</div>\n    <button class="btn-print" onclick="window.print()">🖨️ Imprimir / Guardar PDF Ahora</button>\n  </div>\n\n  ${tieneImg ? `\n  <div class="page-sheet">\n    <div class="header-banner">\n      <div style="display:flex; align-items:center; gap:12px;">\n        <img src="${window.location.origin}/static/assets/circulo_azul_diabetes.svg" style="width:44px; height:44px; border-radius:10px; background:#fff;" alt="Círculo Azul Diabetes" />\n        <div>\n          <h1>LABORATORIO DE ESTUDIO DE DIABETES PARA ENFERMERÍA</h1>\n          <p>Escuela de Educación en Diabetes (60 hs) • Dirección Académica: Dr. Marcos Gamond</p>\n        </div>\n      </div>\n      <div style="font-size:12px; font-weight:800; color:#38bdf8;">INFOGRAFÍA OFICIAL • UNIDAD ${u.numero}</div>\n    </div>\n    <div class="unit-title-bar">\n      <h2>${u.icono} ${u.titulo}</h2>\n      <p>${u.resumen}</p>\n    </div>\n    <div class="full-img-wrapper">\n      <img src="${imgUrl}" alt="Infografía Unidad ${u.numero}" onload="setTimeout(() => window.print(), 350)" />\n    </div>\n  </div>\n  ` : ""}\n\n  <div class="page-sheet">\n    <div class="header-banner">\n      <div style="display:flex; align-items:center; gap:12px;">\n        <img src="${window.location.origin}/static/assets/circulo_azul_diabetes.svg" style="width:44px; height:44px; border-radius:10px; background:#fff;" alt="Círculo Azul Diabetes" />\n        <div>\n          <h1>LABORATORIO DE ESTUDIO DE DIABETES PARA ENFERMERÍA</h1>\n          <p>Escuela de Educación en Diabetes (60 hs) • Dirección Académica: Dr. Marcos Gamond</p>\n        </div>\n      </div>\n      <div style="font-size:12px; font-weight:800; color:#38bdf8;">LÁMINA CLÍNICA DE GUARDIA • UNIDAD ${u.numero}</div>\n    </div>\n\n    <div class="unit-title-bar">\n      <h2>${u.icono} ${u.titulo}</h2>\n      <p><strong>Módulo:</strong> ${u.modulo} • <strong>Fuente:</strong> ${(u.guias_consenso && u.guias_consenso.fuente) || "ADA / SAD"}</p>\n    </div>\n\n    <div class="grid-4">\n      ${pasosHtml}\n    </div>\n\n    <div class="section-box">\n      <h3>⚡ Lectura Rápida en 3 Minutos</h3>\n      <ul>${lecturaHtml}</ul>\n    </div>\n\n    <div class="gold-rule">\n      <strong>🚨 REGLA SALVAVIDAS DE LA UNIDAD:</strong><br/>\n      ${(u.guias_consenso && u.guias_consenso.regla_enfermeria) || ""}\n    </div>\n\n    <div class="section-box">\n      <h3>📊 Tabla Clínica de Bolsillo</h3>\n      <table>\n        <thead>\n          <tr>\n            <th>Criterio / Escenario</th>\n            <th>Parámetro / Estrategia</th>\n            <th>Conducta de Enfermería</th>\n            <th>Punto Crítico / Error a Evitar</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${filasTablaHtml}\n        </tbody>\n      </table>\n    </div>\n\n    <div class="section-box" style="background:#f8fafc; margin-top:8px;">\n      <h3>🔤 Referencia de Siglas y Abreviaturas de la Unidad ${u.numero}</h3>\n      <div style="font-size:10.5px; line-height:1.45; color:#1e293b;">\n        ${obtenerHtmlSiglasImpresion(u.numero)}\n      </div>\n    </div>\n  </div>\n\n  ${!tieneImg ? `<script>window.onload = function() { setTimeout(function() { window.print(); }, 300); };<\\/script>` : ""}\n</body>\n</html>`);\n  printWin.document.close();\n}\n\n// ============================================================================\n// DICCIONARIO OFICIAL DE SIGLAS Y ABREVIATURAS CLÍNICAS EN DIABETES (UNIDADES 1 A 10)\n// ============================================================================\nconst GLOSARIO_SIGLAS_DIABETES = [\n  // UNIDAD 1: Fisiopatología, Clasificación y Diagnóstico (PTOG, HbA1c, GAA, ITG)\n  { sigla: "PTOG", nombre: "Prueba de Tolerancia Oral a la Glucosa (Curva de 75 g)", unidad: 1, explicacion: "Estudio diagnóstico donde se mide glucemia en ayunas y exactamente 2 horas después de beber 75 g de glucosa anhidra en 300 mL de agua en 5-10 min." },\n  { sigla: "HbA1c / A1c", nombre: "Hemoglobina Glicosilada (Fracción A1c)", unidad: 1, explicacion: "Refleja el promedio de glucemia de los últimos 90 a 120 días (vida media del glóbulo rojo). No requiere ayuno y se extrae en tubo con EDTA (tapa violeta)." },\n  { sigla: "GAA", nombre: "Glucemia Alterada en Ayunas (Prediabetes)", unidad: 1, explicacion: "Glucemia plasmática venosa en ayunas entre 100 y 125 mg/dL." },\n  { sigla: "ITG", nombre: "Intolerancia a la Tolerancia a la Glucosa (Prediabetes)", unidad: 1, explicacion: "Glucemia a las 2 horas de la PTOG entre 140 y 199 mg/dL." },\n  { sigla: "DBT1 / DM1", nombre: "Diabetes Mellitus Tipo 1", unidad: 1, explicacion: "Destrucción autoinmune de las células Beta pancreáticas con déficit absoluto de insulina y tendencia a la cetosis." },\n  { sigla: "DBT2 / DM2", nombre: "Diabetes Mellitus Tipo 2", unidad: 1, explicacion: "Combinación de resistencia periférica a la insulina y falla progresiva de la célula Beta." },\n  { sigla: "Las 4 P", nombre: "Poliuria, Polidipsia, Polifagia y Pérdida de Peso", unidad: 1, explicacion: "Los 4 síntomas cardinales clásicos de hiperglucemia severa y catabolismo." },\n  { sigla: "GLUT-4", nombre: "Transportador de Glucosa Tipo 4", unidad: 1, explicacion: "Canal proteico en músculo y tejido adiposo que requiere insulina (o contracción muscular en el ejercicio) para abrirse e ingresar glucosa a la célula." },\n  { sigla: "EDTA", nombre: "Ácido Etilendiaminotetraacético (Tubo Tapa Violeta)", unidad: 1, explicacion: "Anticoagulante utilizado en el tubo de sangre entera para medir Hemoglobina Glicosilada (HbA1c)." },\n\n  // UNIDAD 2: Diabetes Tipo 1, Luna de Miel y Sensores de Glucosa (CGM)\n  { sigla: "MCG / CGM", nombre: "Monitoreo Continuo de Glucosa (Sensor Intersticial)", unidad: 2, explicacion: "Sensor colocado en tejido celular subcutáneo que mide la glucosa en el líquido intersticial (con un retraso fisiológico o \'lag time\' de 10 a 15 minutos respecto a la sangre)." },\n  { sigla: "TIR", nombre: "Tiempo en Rango (Time in Range: 70–180 mg/dL)", unidad: 2, explicacion: "Porcentaje del día que el paciente permanece con glucemias entre 70 y 180 mg/dL. La meta estándar es superar el 70% (>16 hs 48 min por día)." },\n  { sigla: "TBR y TAR", nombre: "Tiempo Bajo Rango (<70 mg/dL) y Tiempo Sobre Rango (>180 mg/dL)", unidad: 2, explicacion: "Métricas del sensor MCG: el TBR (<70 mg/dL) debe ser menor al 4% (<1 hora/día) para prevenir hipoglucemias." },\n  { sigla: "HGT", nombre: "Hemoglucotest (Glucemia Capilar por Punción Digital)", unidad: 2, explicacion: "Medición de glucosa en sangre capilar obtenida en la cara lateral del pulpejo del dedo con glucómetro y tira reactiva. Obligatorio para confirmar si los síntomas no coinciden con el sensor." },\n  { sigla: "LADA", nombre: "Diabetes Autoinmune Latente del Adulto", unidad: 2, explicacion: "Diabetes autoinmune de aparición en adultos (>30 años), a menudo delgados, que fracasan rápido a antidiabéticos orales y requieren insulina." },\n\n  // UNIDAD 3: Diabetes Tipo 2, Insulinorresistencia y Enfoque Cardiometabólico\n  { sigla: "IGF-1", nombre: "Factor de Crecimiento Similar a la Insulina Tipo 1", unidad: 3, explicacion: "Receptor cutáneo estimulado por el exceso de insulina circulante (hiperinsulinemia compensatoria), causando Acantosis Nigricans y acrocordones en cuello y axilas." },\n  { sigla: "GLP-1 y GIP", nombre: "Péptido Similar al Glucagón 1 / Polipéptido Insulinotrópico", unidad: 3, explicacion: "Hormonas incretinas liberadas por el intestino al comer que estimulan el 60-70% de la secreción de insulina postprandial y frenan al glucagón." },\n  { sigla: "RAC", nombre: "Relación Albúmina/Creatinina en Orina Aislada", unidad: 3, explicacion: "Estudio anual de detección precoz de nefropatía diabética (normal <30 mg/g)." },\n  { sigla: "PA", nombre: "Presión Arterial", unidad: 3, explicacion: "Meta en personas con diabetes e hipertensión: <130/80 mmHg para protección cardio-renal." },\n\n  // UNIDAD 4\n  { sigla: "DG", nombre: "Diabetes Gestacional", unidad: 4, explicacion: "Alteración del metabolismo de los hidratos de carbono diagnosticada por primera vez durante el embarazo (usualmente en semanas 24 a 28 por hormonas placentarias)." },\n  { sigla: "ALAD / SAD", nombre: "Asociación Latinoamericana de Diabetes / Sociedad Argentina de Diabetes", unidad: 4, explicacion: "Consensos adoptados en Argentina donde la Diabetes Gestacional se diagnostica con ayunas ≥100 mg/dL (en 2 determinaciones) o PTOG a las 2 hs ≥140 mg/dL." },\n  { sigla: "IADPSG", nombre: "Asociación Internacional de Grupos de Estudio de Diabetes y Embarazo", unidad: 4, explicacion: "Criterio internacional de un solo paso para embarazo con puntos de corte 92 mg/dL (ayunas), 180 mg/dL (1 h) y 153 mg/dL (2 hs)." },\n\n  // UNIDAD 5\n  { sigla: "ADA", nombre: "American Diabetes Association (Asociación Americana de Diabetes)", unidad: 5, explicacion: "Organismo que publica anualmente los \'Standards of Care in Diabetes\' y el Método del Plato Nutricional (50% vegetales sin almidón, 25% proteínas, 25% carbohidratos)." },\n  { sigla: "AMPK", nombre: "Proteína Quinasa Activada por AMP", unidad: 5, explicacion: "Vía enzimática activada por la contracción muscular durante el ejercicio que trasloca los canales GLUT-4 a la membrana sin depender de la insulina." },\n  { sigla: "HC / CHO", nombre: "Hidratos de Carbono (Carbohidratos)", unidad: 5, explicacion: "Macronutriente de mayor impacto directo en la glucemia postprandial (simples de absorción rápida vs complejos ricos en fibra)." },\n\n  // UNIDAD 6\n  { sigla: "FITTER", nombre: "Consenso Internacional sobre Técnica de Inyección de Insulina", unidad: 6, explicacion: "Guía mundial de enfermería que establece el uso de agujas cortas de 4 mm a 90°, purgado de 1-2 UI, espera de 10 segundos y rotación de sitios." },\n  { sigla: "NPH", nombre: "Insulina Neutral Protamine Hagedorn (Insulina Intermedia Turbia)", unidad: 6, explicacion: "Insulina basal humana de aspecto lechoso que requiere resuspenderse rolándola 20 veces entre las palmas y tiene un pico de riesgo de hipoglucemia entre las 4 y 10 horas." },\n  { sigla: "UI", nombre: "Unidades Internacionales", unidad: 6, explicacion: "Medida de dosificación de la insulina (en Argentina los frascos y lapiceras estándar tienen concentración U-100: 100 UI por cada 1 mL)." },\n  { sigla: "SC / EV / IM", nombre: "Subcutánea / Endovenosa / Intramuscular", unidad: 6, explicacion: "Vías de administración parenteral. Todas las insulinas van por vía SC; la ÚNICA insulina apta para vía EV es la Insulina Corriente (Regular/Cristalina)." },\n\n  // UNIDAD 7\n  { sigla: "ADO", nombre: "Antidiabéticos Orales", unidad: 7, explicacion: "Fármacos no insulínicos administrados por vía oral (Metformina, Sulfonilureas, iDPP-4, iSGLT2)." },\n  { sigla: "iSGLT2", nombre: "Inhibidores del Cotransportador Sodio-Glucosa Tipo 2 (Gliflozinas)", unidad: 7, explicacion: "Fármacos (Empagliflozina, Dapagliflozina) que eliminan glucosa por orina y protegen corazón/riñón. Se suspenden 3-4 días antes de cirugías por riesgo de Cetoacidosis Euglucémica." },\n  { sigla: "iDPP-4", nombre: "Inhibidores de la Dipeptidil Peptidasa-4 (Gliptinas)", unidad: 7, explicacion: "Fármacos orales neutros que no causan hipoglucemia (Sitagliptina, Vildagliptina, Linagliptina). La Linagliptina no requiere ajuste en insuficiencia renal ni diálisis." },\n  { sigla: "TFG / VFG", nombre: "Tasa de Filtrado Glomerular (Función Renal)", unidad: 7, explicacion: "Indicador de función renal. Si la TFG es <30 mL/min/1.73m², está contraindicada la Metformina por riesgo de acidosis láctica." },\n  { sigla: "NPO", nombre: "Nada Por Boca (Ayuno Indicado en Internación)", unidad: 7, explicacion: "Indicación hospitalaria de suspensión de ingesta oral; obliga a suspender de inmediato Sulfonilureas e insulinas prandiales." },\n\n  // UNIDAD 8\n  { sigla: "CAD", nombre: "Cetoacidosis Diabética", unidad: 8, explicacion: "Emergencia hiperglucémica por déficit absoluto de insulina con cetonemia/cetonuria positiva, acidosis metabólica (pH <7.30, bicarbonato <18) y respiración de Kussmaul." },\n  { sigla: "EHH / EHHNC", nombre: "Estado Hiperosmolar Hiperglucémico", unidad: 8, explicacion: "Emergencia típica de adultos mayores con DBT2 caracterizada por glucemias >600 mg/dL, osmolaridad >320 mOsm/kg y deshidratación severa sin cetoacidosis significativa." },\n  { sigla: "BIC", nombre: "Bomba de Infusión Continua", unidad: 8, explicacion: "Dispositivo electrónico para infundir Insulina Corriente endovenosa (100 UI en 100 mL de SF 0.9% = relación 1:1) a 0.1 UI/kg/h." },\n  { sigla: "SF 0.9%", nombre: "Solución Fisiológica (Cloruro de Sodio al 0,9%)", unidad: 8, explicacion: "Cristaloide de primera línea para la expansión volémica inicial en CAD y EHH antes de iniciar la insulina." },\n\n  // UNIDAD 9\n  { sigla: "IWGDF", nombre: "International Working Group on the Diabetic Foot (Grupo Internacional de Pie Diabético)", unidad: 9, explicacion: "Consenso mundial rector para la prevención, clasificación y tratamiento de las úlceras del pie diabético." },\n  { sigla: "SINBAD", nombre: "Escala de Clasificación de Úlceras (Site, Ischemia, Neuropathy, Bacterial infection, Area, Depth)", unidad: 9, explicacion: "Puntaje de 0 a 6 que evalúa Sitio, Isquemia, Neuropatía, Infección Bacteriana, Área y Profundidad. Un puntaje ≥3 exige derivación urgente a equipo especializado." },\n  { sigla: "PSP", nombre: "Pérdida de la Sensibilidad Protectora", unidad: 9, explicacion: "Ausencia de percepción del monofilamento de 10 g de Semmes-Weinstein en al menos uno de los puntos plantares evaluados (\'anestesia protectora\')." },\n  { sigla: "EAP / ITB", nombre: "Enfermedad Arterial Periférica / Índice Tobillo-Brazo", unidad: 9, explicacion: "Compromiso circulatorio isquémico del miembro inferior evaluado por palpación de pulsos pedio/tibial posterior e índice Doppler Tobillo-Brazo." },\n\n  // UNIDAD 10\n  { sigla: "DSMES", nombre: "Educación y Apoyo para el Automanejo de la Diabetes", unidad: 10, explicacion: "Proceso educativo centrado en la persona y su familia (ADA/SAD) para adquirir destrezas seguras de autocuidado." },\n  { sigla: "Teach-Back", nombre: "Método de Re-enseñanza o Demostración Inversa", unidad: 10, explicacion: "Técnica de validación al alta donde el paciente demuestra en vivo cómo carga la lapicera, quita ambos capuchones y explica con sus palabras qué hacer ante una hipoglucemia." },\n  { sigla: "SADMANS", nombre: "Sulfonilureas, AiECA (IECA), Diuréticos, Metformina, ARA-II, NAINEs (AINEs) y SGLT2", unidad: 10, explicacion: "Acrónimo de los 7 grupos de fármacos que deben pausarse transitoriamente cuando el paciente sufre vómitos, diarrea o deshidratación aguda." },\n  { sigla: "IECA / ARA-II / AINEs", nombre: "Inhibidores de la Enzima Convertidora / Antagonistas del Receptor de Angiotensina / Antiinflamatorios No Esteroideos", unidad: 10, explicacion: "Fármacos antihipertensivos (ej. Enalapril, Losartán) y analgésicos (ej. Ibuprofeno, Diclofenac) incluidos en la pausa SADMANS por riesgo de injuria renal aguda en deshidratación." }\n];\n\nfunction renderSiglasUnidadActual(unitNum) {\n  const box = document.getElementById("unitSiglasContainer");\n  if (!box) return;\n  const items = GLOSARIO_SIGLAS_DIABETES.filter(x => x.unidad === Number(unitNum));\n  box.innerHTML = items.map(item => `\n    <span class="sigla-chip-item" title="${item.explicacion}">\n      <strong>${item.sigla}:</strong> ${item.nombre}\n    </span>\n  `).join("");\n}\n\nfunction obtenerHtmlSiglasImpresion(unitNum) {\n  const items = GLOSARIO_SIGLAS_DIABETES.filter(x => x.unidad === Number(unitNum));\n  return items.map(item => `<span style="display:inline-block; margin-right:12px; margin-bottom:3px;"><strong>• ${item.sigla}:</strong> ${item.nombre} <em>(${item.explicacion})</em></span>`).join("<br/>");\n}\n\nfunction abrirModalGlosarioSiglas() {\n  const modal = document.getElementById("modalGlosarioSiglas");\n  if (!modal) return;\n  modal.style.display = "flex";\n  filtrarGlosarioSiglas();\n}\n\nfunction cerrarModalGlosarioSiglas() {\n  const modal = document.getElementById("modalGlosarioSiglas");\n  if (modal) modal.style.display = "none";\n}\n\nfunction filtrarGlosarioSiglas() {\n  const q = (document.getElementById("inputBuscarSigla")?.value || "").trim().toLowerCase();\n  const uSel = document.getElementById("selectFiltroUnidadSigla")?.value || "todas";\n  const listEl = document.getElementById("glosarioSiglasModalList");\n  if (!listEl) return;\n\n  const filtrados = GLOSARIO_SIGLAS_DIABETES.filter(item => {\n    const matchUnit = uSel === "todas" || String(item.unidad) === String(uSel);\n    const matchText = !q ||\n      item.sigla.toLowerCase().includes(q) ||\n      item.nombre.toLowerCase().includes(q) ||\n      item.explicacion.toLowerCase().includes(q);\n    return matchUnit && matchText;\n  });\n\n  if (!filtrados.length) {\n    listEl.innerHTML = `<div style="grid-column:1/-1; padding:18px; text-align:center; color:#64748b;">No se encontraron siglas que coincidan con la búsqueda.</div>`;\n    return;\n  }\n\n  listEl.innerHTML = filtrados.map(item => `\n    <div class="sigla-dict-card">\n      <div class="sigla-head">\n        <span class="sigla-code">${item.sigla}</span>\n        <span class="sigla-unit-badge">Unidad ${item.unidad}</span>\n      </div>\n      <div class="sigla-full">${item.nombre}</div>\n      <div class="sigla-desc">${item.explicacion}</div>\n    </div>\n  `).join("");\n}\n\nfunction imprimirGlosarioSiglasCompleto() {\n  const w = window.open("", "_blank", "width=980,height=850");\n  if (!w) return;\n  const rowsHtml = GLOSARIO_SIGLAS_DIABETES.map(item => `\n    <tr>\n      <td style="font-weight:800; color:#0369a1; white-space:nowrap;">${item.sigla}</td>\n      <td style="font-weight:700;">${item.nombre}</td>\n      <td>${item.explicacion}</td>\n      <td style="text-align:center; font-weight:700;">U${item.unidad}</td>\n    </tr>\n  `).join("");\n\n  w.document.write(`<!DOCTYPE html>\n<html lang="es">\n<head>\n  <meta charset="UTF-8" />\n  <title>Diccionario de Siglas y Abreviaturas en Diabetes — Dr. Marcos Gamond</title>\n  <style>\n    @page { size: A4 portrait; margin: 10mm; }\n    body { font-family: \'Segoe UI\', Arial, sans-serif; color: #0f172a; margin: 0; }\n    .head { background: #0f172a; color: #fff; padding: 14px 18px; border-radius: 10px; margin-bottom: 12px; display:flex; justify-content:space-between; align-items:center; }\n    .head h1 { font-size: 15px; margin: 0; }\n    .head p { font-size: 11px; margin: 3px 0 0; color: #bae6fd; }\n    table { width: 100%; border-collapse: collapse; font-size: 10.5px; }\n    th { background: #0284c7; color: #fff; text-align: left; padding: 6px 8px; }\n    td { border: 1px solid #cbd5e1; padding: 5px 8px; vertical-align: top; }\n    tr:nth-child(even) { background: #f8fafc; }\n  </style>\n</head>\n<body onload="setTimeout(() => window.print(), 300)">\n  <div class="head">\n    <div>\n      <h1>DICCIONARIO DE SIGLAS Y ABREVIATURAS CLÍNICAS EN DIABETES PARA ENFERMERÍA</h1>\n      <p>Laboratorio de Estudio de Diabetes para Enfermería (60 hs) • Dirección Académica: Dr. Marcos Gamond</p>\n    </div>\n    <div style="font-size:11px; font-weight:800; color:#38bdf8;">UNIDADES 1 A 10</div>\n  </div>\n  <table>\n    <thead>\n      <tr>\n        <th>Sigla</th>\n        <th>Significado Completo</th>\n        <th>Aplicación Clínica para Enfermería</th>\n        <th>Unidad</th>\n      </tr>\n    </thead>\n    <tbody>\n      ${rowsHtml}\n    </tbody>\n  </table>\n</body>\n</html>`);\n  w.document.close();\n}\n\nfunction switchUnitStep(paneId, btnEl) {\n  document.querySelectorAll(".unit-step-pane").forEach(p => p.style.display = "none");\n  document.querySelectorAll(".unit-subtabs .subtab-btn").forEach(b => b.classList.remove("active"));\n  document.getElementById(paneId).style.display = "block";\n  if (btnEl) btnEl.classList.add("active");\n}\n\nfunction goToNextUnitTab(tabIndex) {\n  const panes = ["stepMedia", "stepFisio", "stepGuias", "stepCaso", "stepQuiz"];\n  const btns = document.querySelectorAll(".unit-subtabs .subtab-btn");\n  switchUnitStep(panes[tabIndex], btns[tabIndex]);\n}\n\nfunction renderUnitQuiz(u) {\n  const qBox = document.getElementById("unitQuizQuestionsBox");\n  const banner = document.getElementById("unitQuizResultBanner");\n  banner.style.display = "none";\n  qBox.innerHTML = "";\n\n  u.autoevaluacion.forEach((q, qIdx) => {\n    const card = document.createElement("div");\n    card.className = "quiz-question-card";\n    const optsHtml = q.opciones.map((optText, optIdx) => `\n      <label class="quiz-option-label" id="lbl_${qIdx}_${optIdx}">\n        <input type="radio" name="unit_q_${qIdx}" value="${optIdx}" style="margin-right:8px;" />\n        ${optText}\n      </label>\n    `).join("");\n\n    card.innerHTML = `\n      <div style="font-weight:800; font-size:0.96rem; color:#0f172a; margin-bottom:8px;">${q.pregunta}</div>\n      <div>${optsHtml}</div>\n      <div id="exp_q_${qIdx}" class="quiz-explanation"></div>\n    `;\n    qBox.appendChild(card);\n  });\n}\n\nfunction calificarAutoevaluacion() {\n  const u = UNIDADES[currentUnitIdx];\n  const preguntas = u.autoevaluacion;\n  let aciertos = 0;\n\n  preguntas.forEach((q, qIdx) => {\n    const sel = document.querySelector(`input[name="unit_q_${qIdx}"]:checked`);\n    const expBox = document.getElementById(`exp_q_${qIdx}`);\n    expBox.style.display = "block";\n\n    if (sel) {\n      const val = parseInt(sel.value, 10);\n      if (val === q.correcta) {\n        aciertos++;\n        expBox.style.background = "#dcfce7";\n        expBox.style.color = "#14532d";\n        expBox.innerHTML = `✅ <strong>¡Correcto!</strong> ${q.explicacion}`;\n      } else {\n        expBox.style.background = "#ffe4e6";\n        expBox.style.color = "#881337";\n        expBox.innerHTML = `❌ <strong>Respuesta incorrecta.</strong> Fundamento de Guía: ${q.explicacion}`;\n      }\n    } else {\n      expBox.style.background = "#fef3c7";\n      expBox.style.color = "#92400e";\n      expBox.innerHTML = `⚠️ Seleccioná una opción para esta pregunta.`;\n    }\n  });\n\n  const banner = document.getElementById("unitQuizResultBanner");\n  banner.style.display = "block";\n  const pct = Math.round((aciertos / preguntas.length) * 100);\n\n  if (aciertos >= 2) {\n    saveApprovedUnit(u.id, pct);\n    renderUnitsSidebar();\n    document.getElementById("unitApprovalStamp").innerHTML =\n      `<span class="unit-status-badge done" style="font-size:0.85rem; padding:6px 14px;">🏆 Unidad Aprobada (${pct}%)</span>`;\n\n    const nextIdx = currentUnitIdx + 1;\n    const nextBtnHtml = nextIdx < UNIDADES.length\n      ? `<button class="subtab-btn active" style="margin-top:10px;" onclick="selectUnit(${nextIdx})">Avanzar a la Unidad ${nextIdx + 1} ➔</button>`\n      : `<div style="margin-top:10px; font-weight:800;">🎓 ¡Felicitaciones! Completaste la última unidad del programa.</div>`;\n\n    banner.style.background = "#ecfdf5";\n    banner.style.borderColor = "#10b981";\n    banner.style.color = "#065f46";\n    banner.innerHTML = `\n      <strong>🏆 ¡UNIDAD ${u.numero} APROBADA! Calificación: ${aciertos} de ${preguntas.length} (${pct}%)</strong><br>\n      Tu progreso quedó registrado en tu historial académico asincrónico.\n      <div>${nextBtnHtml}</div>\n    `;\n  } else {\n    banner.style.background = "#fff1f2";\n    banner.style.borderColor = "#f43f5e";\n    banner.style.color = "#881337";\n    banner.innerHTML = `\n      <strong>⚠️ Calificación: ${aciertos} de ${preguntas.length} (${pct}%) — Se requieren al menos 2 respuestas correctas para aprobar la unidad.</strong><br>\n      Revisá las explicaciones arriba y volvé a intentarlo.\n    `;\n  }\n}\n\n// ============================================================================\n// 2. MOTOR DE ÁRBOLES DE DECISIÓN PASO A PASO\n// ============================================================================\nfunction loadAlgorithm(algoId) {\n  currentAlgoId = algoId;\n  const algo = ALGORITMOS[algoId];\n  if (!algo) return;\n  document.getElementById("algoGuiaTag").textContent = algo.guia_base;\n  document.getElementById("algoMainTitle").textContent = algo.nombre;\n  renderAlgoNode(algo.nodo_inicial);\n}\n\nfunction renderAlgoNode(nodeKey) {\n  const algo = ALGORITMOS[currentAlgoId];\n  const node = algo.nodos[nodeKey];\n  if (!node) return;\n\n  document.getElementById("algoNodeQuestion").textContent = node.pregunta;\n  document.getElementById("algoNodeContext").textContent = node.contexto;\n\n  const optsBox = document.getElementById("algoOptionsContainer");\n  optsBox.innerHTML = "";\n  node.opciones.forEach(op => {\n    const btn = document.createElement("button");\n    btn.className = "algo-option-btn";\n    btn.textContent = op.texto;\n    btn.onclick = () => renderAlgoNode(op.ir_a);\n    optsBox.appendChild(btn);\n  });\n}\n\n// ============================================================================\n// 3. CALCULADORAS CLÍNICAS DE GUARDIA\n// ============================================================================\nfunction calcularBombaEV() {\n  const peso = parseFloat(document.getElementById("calcPeso").value) || 70;\n  const glu = parseFloat(document.getElementById("calcGlucemia").value) || 350;\n  const k = parseFloat(document.getElementById("calcPotasio").value) || 4.0;\n  const box = document.getElementById("resBombaBox");\n\n  if (k < 3.3) {\n    box.style.background = "#ffe4e6";\n    box.style.borderColor = "#f43f5e";\n    box.style.color = "#881337";\n    box.innerHTML = `\n      <strong>🛑 FRENO CRÍTICO DE SEGURIDAD (Guía SAD / ADA Nivel A):</strong><br>\n      El Potasio sérico es <strong>${k.toFixed(1)} mEq/L (&lt; 3.3 mEq/L)</strong>.<br>\n      • <strong>PROHIBIDO iniciar la Bomba de Insulina EV ahora</strong> (riesgo de hipokalemia letal y arritmia ventricular).<br>\n      • <strong>Acción inmediata:</strong> Expandir con Solución Fisiológica 0.9% y administrar carga de Cloruro de Potasio (KCl) EV hasta documentar K+ ≥ 3.3 mEq/L.\n    `;\n    return;\n  }\n\n  const esBajaGlucemia = glu < 250;\n  const factor = esBajaGlucemia ? 0.05 : 0.1;\n  const uiHora = (peso * factor).toFixed(1);\n\n  box.style.background = "#ecfdf5";\n  box.style.borderColor = "#10b981";\n  box.style.color = "#065f46";\n  box.innerHTML = `\n    <strong>✅ AUDITORÍA DE POTASIO SEGURA (K+ = ${k.toFixed(1)} mEq/L):</strong><br>\n    • <strong>Preparación Estándar:</strong> 100 UI de Insulina Corriente (Cristalina) en 100 ml de SF 0.9% (<strong>1 ml = 1 UI</strong>). Purgar 20 ml en la tubuladura.<br>\n    • <strong>Velocidad de Infusión (${factor} UI/kg/h):</strong> <strong>${uiHora} ml/hora</strong> (= ${uiHora} UI/h).<br>\n    ${esBajaGlucemia\n      ? "⚠️ <strong>Alerta Glucemia &lt; 250 mg/dL:</strong> Agregar paralelo de <strong>Dextrosa al 5% o 10%</strong> y mantener la bomba a mitad de dosis hasta cerrar acidosis (pH &gt; 7.30)."\n      : "📌 <strong>Monitoreo:</strong> Control de HGT horario. Meta de descenso: 50 a 75 mg/dL por hora."}\n  `;\n}\n\nfunction calcularSinbad() {\n  let pts = 0;\n  document.querySelectorAll(".sinbad-chk:checked").forEach(c => {\n    pts += parseInt(c.value, 10);\n  });\n  const box = document.getElementById("resSinbadBox");\n\n  if (pts >= 3) {\n    box.style.background = "#fff1f2";\n    box.style.borderColor = "#f43f5e";\n    box.style.color = "#881337";\n    box.innerHTML = `\n      <strong>🚨 PUNTAJE SINBAD: ${pts} / 6 (ALTO RIESGO DE AMPUTACIÓN — Guía IWGDF / MSAL)</strong><br>\n      • <strong>Conducta obligatoria:</strong> Derivación urgente (en &lt; 24–48 hs) a Equipo Multidisciplinario de Pie Diabético / Cirugía Vascular.<br>\n      • Descarga total de apoyo plantar y toma de cultivo profundo si hay signos de infección.\n    `;\n  } else {\n    box.style.background = "#ecfdf5";\n    box.style.borderColor = "#10b981";\n    box.style.color = "#065f46";\n    box.innerHTML = `\n      <strong>🟢 PUNTAJE SINBAD: ${pts} / 6 (ÚLCERA DE RIESGO BAJO / MODERADO)</strong><br>\n      • <strong>Conducta según Guía IWGDF:</strong> Descarga estricta de presión en la zona ulcerada, curación húmeda acorde al lecho y reevaluación en 1 semana.\n    `;\n  }\n}\n\n// ============================================================================\n// 4. COPILOTO CLÍNICO RAG ESTILO NOTEBOOKLM (10 UNIDADES + GUÍAS OFICIALES)\n// ============================================================================\nlet ultimaRespuestaCopilotoTexto = "";\n\nfunction presetQuery(text) {\n  const inp = document.getElementById("copilotoInput");\n  if (inp) {\n    inp.value = text;\n  }\n  enviarConsultaCopiloto();\n}\n\nfunction abrirCopilotoEnUnidadActual() {\n  const u = UNIDADES[currentUnitIdx];\n  const navBtns = document.querySelectorAll(".nav-pills .nav-btn");\n  openTab("tabCopiloto", navBtns[3]);\n\n  const scopeSel = document.getElementById("ragScopeSelect");\n  if (scopeSel && u) {\n    scopeSel.value = "u" + u.numero;\n  }\n\n  const inp = document.getElementById("copilotoInput");\n  if (inp && u) {\n    inp.placeholder = `Consultale a GLUC-IA sobre la Unidad ${u.numero} (${u.titulo})...`;\n    inp.focus();\n  }\n}\n\nfunction irAUnidadDesdeCita(unitNum) {\n  if (!unitNum || unitNum < 1 || unitNum > UNIDADES.length) return;\n  const navBtns = document.querySelectorAll(".nav-pills .nav-btn");\n  openTab("tabCampus", navBtns[0]);\n  selectUnit(unitNum - 1);\n  window.scrollTo({ top: 0, behavior: "smooth" });\n}\n\nfunction formatearMarkdownRag(mdText) {\n  if (!mdText) return "";\n  let html = mdText\n    .replace(/### (.*)/g, "<h4 style=\'color:#38bdf8; font-size:1.03rem; margin:14px 0 6px 0; font-weight:800;\'>$1</h4>")\n    .replace(/\\*\\*(.*?)\\*\\*/g, "<strong style=\'color:#f8fafc; background:rgba(56,189,248,0.14); padding:0 4px; border-radius:4px;\'>$1</strong>")\n    .replace(/\\[(\\d+)\\]/g, "<span style=\'background:#0284c7; color:#fff; font-size:0.72rem; font-weight:800; padding:1px 6px; border-radius:99px; margin:0 2px;\'>Ref. $1</span>")\n    .replace(/\\n\\n/g, "<br><br>")\n    .replace(/\\n• /g, "<br>• ")\n    .replace(/\\n\\* /g, "<br>• ")\n    .replace(/\\n/g, "<br>");\n  return html;\n}\n\nfunction responderCopilotoLocal(consulta, alcance) {\n  const q = (consulta || "").toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g, "");\n  const palabras = q.split(/\\s+/).filter(w => w.length >= 2);\n  const hallazgos = [];\n\n  // 1. Buscar en el Glosario de Siglas\n  GLOSARIO_SIGLAS_DIABETES.forEach(s => {\n    const texto = `${s.sigla} ${s.nombre} ${s.explicacion}`.toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g, "");\n    let score = 0;\n    palabras.forEach(w => { if (texto.includes(w)) score += 3; });\n    if (q.includes(s.sigla.toLowerCase())) score += 10;\n    if (score > 0) {\n      hallazgos.push({\n        score,\n        unidad_num: s.unidad,\n        fuente: `Diccionario Clínico de Siglas (Unidad ${s.unidad})`,\n        titulo: `${s.sigla} — ${s.nombre}`,\n        extracto: s.explicacion\n      });\n    }\n  });\n\n  // 2. Buscar en las 10 Unidades del Programa\n  UNIDADES.forEach(u => {\n    if (alcance && alcance.startsWith("u") && alcance !== ("u" + u.numero)) return;\n    const regla = (u.guias_consenso && u.guias_consenso.regla_enfermeria) || "";\n    const l3 = ((u.multimedia && u.multimedia.lectura_3_minutos) || []).join(" ");\n    const cardsTxt = (u.fisiopatologia_cards || []).map(c => `${c.titulo}: ${c.contenido}`).join(" ");\n    const bloque = `${u.titulo} ${u.resumen} ${regla} ${l3} ${cardsTxt}`.toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g, "");\n    let score = 0;\n    palabras.forEach(w => { if (bloque.includes(w)) score += 2; });\n    if (score > 0) {\n      hallazgos.push({\n        score,\n        unidad_num: u.numero,\n        fuente: `Unidad ${u.numero} (${u.modulo})`,\n        titulo: u.titulo,\n        extracto: `${regla} ${(u.multimedia && u.multimedia.lectura_3_minutos && u.multimedia.lectura_3_minutos[0]) || u.resumen}`\n      });\n    }\n  });\n\n  hallazgos.sort((a, b) => b.score - a.score);\n  const top = hallazgos.slice(0, 3);\n  if (top.length === 0 && UNIDADES.length > 0) {\n    const u0 = UNIDADES[currentUnitIdx] || UNIDADES[0];\n    top.push({\n      score: 1,\n      unidad_num: u0.numero,\n      fuente: `Unidad ${u0.numero}`,\n      titulo: u0.titulo,\n      extracto: (u0.guias_consenso && u0.guias_consenso.regla_enfermeria) || u0.resumen\n    });\n  }\n\n  const cuerpo = top.map((h, i) => `### ${i + 1}. ${h.titulo} [${i + 1}]\\n${h.extracto}`).join("\\n\\n");\n  return {\n    modo: "GLUC-IA • Motor Clínico Integrado (ADA / SAD / MSAL)",\n    respuesta: `**Síntesis Clínica basada en el Programa del Dr. Marcos Gamond:**\\n\\n${cuerpo}`,\n    citas_detalle: top.map((h, i) => ({\n      num: i + 1,\n      unidad_num: h.unidad_num,\n      fuente: h.fuente,\n      titulo: h.titulo,\n      extracto: h.extracto.substring(0, 260) + (h.extracto.length > 260 ? "..." : "")\n    })),\n    preguntas_sugeridas: [\n      "¿Qué significa PTOG y cómo se prepara al paciente?",\n      "¿Cuál es la regla de los 15 en hipoglucemia?",\n      "¿Cuándo se frena la bomba de insulina EV según el potasio?",\n      "¿Qué medicamentos se pausan con la regla SADMANS?"\n    ]\n  };\n}\n\nasync function enviarConsultaCopiloto() {\n  const inp = document.getElementById("copilotoInput");\n  const consulta = (inp ? inp.value : "").trim();\n  const apiKeyEl = document.getElementById("copilotoApiKey");\n  const apiKey = apiKeyEl ? apiKeyEl.value.trim() : "";\n  const scopeSel = document.getElementById("ragScopeSelect");\n  const modeSel = document.getElementById("ragModeSelect");\n  const out = document.getElementById("copilotoOutput");\n\n  if (!consulta || !out) return;\n\n  const alcance = scopeSel ? scopeSel.value : "todas";\n  const modo = modeSel ? modeSel.value : "estudio";\n  const consensoFoco = `${alcance}|${modo}`;\n\n  out.style.display = "block";\n  out.innerHTML = `\n    <div style="color:#7dd3fc; font-weight:700; padding:12px;">\n      ⏳ GLUC-IA está analizando tu consulta en la bibliografía del curso...\n    </div>\n  `;\n\n  try {\n    let res;\n    if (window.__STREAMLIT_STATIC_MODE__) {\n      res = responderCopilotoLocal(consulta, alcance);\n    } else {\n      try {\n        const respHttp = await fetch("/api/copiloto", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify({\n            consulta,\n            consenso_foco: consensoFoco,\n            api_key: apiKey\n          })\n        });\n        if (!respHttp.ok) throw new Error("Fallback local");\n        res = await respHttp.json();\n      } catch (_e) {\n        res = responderCopilotoLocal(consulta, alcance);\n      }\n    }\n\n    ultimaRespuestaCopilotoTexto = (res.respuesta || "").replace(/[#\\*_`]/g, "");\n    const formatted = formatearMarkdownRag(res.respuesta || "");\n\n    // Renderizar tarjetas de respaldo bibliográfico del curso\n    const citasDetalle = res.citas_detalle || [];\n    let citasHtml = "";\n    if (citasDetalle.length > 0) {\n      const cards = citasDetalle.map(c => {\n        const btnUnidad = c.unidad_num && c.unidad_num > 0\n          ? `<button class="quick-chip" style="font-size:0.72rem; padding:3px 9px; background:#0284c7; color:#fff; border:none;" onclick="irAUnidadDesdeCita(${c.unidad_num})">📖 Ir a la Unidad ${c.unidad_num} ➔</button>`\n          : "";\n        return `\n          <div style="background:rgba(15,23,42,0.75); border:1px solid rgba(56,189,248,0.3); border-radius:10px; padding:10px 12px; margin-top:8px;">\n            <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px;">\n              <span style="font-size:0.78rem; font-weight:800; color:#38bdf8;">[Ref. ${c.num}] ${c.fuente} — ${c.titulo}</span>\n              ${btnUnidad}\n            </div>\n            <div style="font-size:0.78rem; color:#cbd5e1; margin-top:5px; line-height:1.45;">\n              «${c.extracto}»\n            </div>\n          </div>\n        `;\n      }).join("");\n\n      citasHtml = `\n        <div style="margin-top:16px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.15);">\n          <div style="font-size:0.8rem; font-weight:800; color:#34d399; margin-bottom:6px;">\n            📚 Respaldo Bibliográfico del Programa y Guías Clínicas:\n          </div>\n          ${cards}\n        </div>\n      `;\n    } else if (res.citas && res.citas.length > 0) {\n      citasHtml = `\n        <div style="margin-top:14px; padding-top:10px; border-top:1px solid rgba(255,255,255,0.15); font-size:0.78rem; color:#94a3b8;">\n          📚 <strong>Fuentes consultadas:</strong> ${res.citas.join(" • ")}\n        </div>\n      `;\n    }\n\n    // Renderizar preguntas de seguimiento sugeridas\n    const sugeridas = res.preguntas_sugeridas || [];\n    let sugeridasHtml = "";\n    if (sugeridas.length > 0) {\n      const chips = sugeridas.map(qText => {\n        const safeQ = qText.replace(/\'/g, "\\\\\'").replace(/"/g, "&quot;");\n        return `<button class="quick-chip" style="font-size:0.76rem; background:rgba(56,189,248,0.12); color:#bae6fd; border-color:rgba(56,189,248,0.35); text-align:left;" onclick="presetQuery(\'${safeQ}\')">💬 ${qText}</button>`;\n      }).join("");\n      sugeridasHtml = `\n        <div style="margin-top:14px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.12);">\n          <div style="font-size:0.78rem; font-weight:800; color:#93c5fd; margin-bottom:8px;">\n            🔍 Preguntas relacionadas para seguir profundizando:\n          </div>\n          <div style="display:flex; flex-wrap:wrap; gap:7px;">\n            ${chips}\n          </div>\n        </div>\n      `;\n    }\n\n    out.innerHTML = `\n      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:10px; padding-bottom:8px; border-bottom:1px solid rgba(255,255,255,0.12);">\n        <span style="font-size:0.75rem; color:#34d399; font-weight:800; text-transform:uppercase;">\n          🩺 ${res.modo}\n        </span>\n        <span style="font-size:0.76rem; color:#bae6fd;">\n          Consulta: <em>«${consulta}»</em>\n        </span>\n      </div>\n      <div style="line-height:1.68; font-size:0.93rem;">${formatted}</div>\n      ${citasHtml}\n      ${sugeridasHtml}\n    `;\n  } catch (err) {\n    out.innerHTML = `<div style="color:#f87171;">❌ Error al consultar a GLUC-IA: ${err.message}</div>`;\n  }\n}\n\nfunction cargarArchivoTextoEnRagInput(inputEl) {\n  if (!inputEl.files || !inputEl.files[0]) return;\n  const file = inputEl.files[0];\n  const titleEl = document.getElementById("newRagDocTitle");\n  if (titleEl && !titleEl.value.trim()) {\n    titleEl.value = file.name.replace(/\\.[^/.]+$/, "");\n  }\n  const reader = new FileReader();\n  reader.onload = function(e) {\n    const contentEl = document.getElementById("newRagDocContent");\n    if (contentEl) {\n      contentEl.value = e.target.result || "";\n    }\n  };\n  reader.readAsText(file, "UTF-8");\n}\n\nasync function guardarNuevoDocumentoRag() {\n  const titulo = (document.getElementById("newRagDocTitle").value || "Apunte Propio").trim();\n  const contenido = (document.getElementById("newRagDocContent").value || "").trim();\n  const st = document.getElementById("newRagDocStatus");\n\n  if (!contenido) {\n    st.style.display = "block";\n    st.style.color = "#fde047";\n    st.textContent = "⚠️ Pegá primero el texto o seleccioná un archivo .txt / .md.";\n    return;\n  }\n\n  st.style.display = "block";\n  st.style.color = "#7dd3fc";\n  st.textContent = "⏳ Incorporando documento a la memoria de GLUC-IA...";\n\n  const comandoEspecial = `ADD_RAG_DOC::${titulo}::Bibliografía del Curso — Dr. Marcos Gamond::${contenido}`;\n  const res = await fetch("/api/copiloto", {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify({ consulta: comandoEspecial, consenso_foco: "todas|estudio" })\n  }).then(r => r.json());\n\n  st.style.color = "#34d399";\n  st.textContent = "✅ ¡Guardado! GLUC-IA ya puede responder consultas sobre «" + titulo + "».";\n  document.getElementById("newRagDocContent").value = "";\n}\n\nfunction narrarUltimaRespuestaCopiloto() {\n  if (!("speechSynthesis" in window)) return;\n  if (!ultimaRespuestaCopilotoTexto) return;\n  window.speechSynthesis.cancel();\n  const utter = new SpeechSynthesisUtterance(ultimaRespuestaCopilotoTexto);\n  utter.lang = "es-AR";\n  utter.rate = 1.03;\n  window.speechSynthesis.speak(utter);\n}\n\nfunction limpiarHistorialCopiloto() {\n  const inp = document.getElementById("copilotoInput");\n  if (inp) inp.value = "";\n  const out = document.getElementById("copilotoOutput");\n  if (out) {\n    out.innerHTML = `\n      <div style="color:#94a3b8; font-size:0.88rem;">\n        ✨ Chat limpio. Escribí cualquier pregunta abierta sobre las 10 Unidades o las Guías Oficiales (ADA • SAD • MSAL • FITTER • IWGDF) o tocá uno de los temas de arriba.\n      </div>\n    `;\n  }\n}\n\ndocument.addEventListener("keydown", function(e) {\n  if (e.target && e.target.id === "copilotoInput" && e.key === "Enter" && !e.shiftKey) {\n    e.preventDefault();\n    enviarConsultaCopiloto();\n  }\n});\n\n'
SVG_DATA_URI = 'data:image/svg+xml;base64,'
INFOGRAFIAS_DATA_URI = {1: 'data:image/jpeg;base64,', 2: 'data:image/jpeg;base64,', 3: 'data:image/jpeg;base64,', 4: 'data:image/jpeg;base64,', 5: 'data:image/jpeg;base64,', 6: 'data:image/jpeg;base64,', 7: 'data:image/jpeg;base64,', 8: 'data:image/jpeg;base64,', 9: 'data:image/jpeg;base64,', 10: 'data:image/jpeg;base64,'}
UNIT_THUMBNAILS_URI = {1: 'data:image/jpeg;base64,', 2: 'data:image/jpeg;base64,', 3: 'data:image/jpeg;base64,', 4: 'data:image/jpeg;base64,', 5: 'data:image/jpeg;base64,', 6: 'data:image/jpeg;base64,', 7: 'data:image/jpeg;base64,', 8: 'data:image/jpeg;base64,', 9: 'data:image/jpeg;base64,', 10: 'data:image/jpeg;base64,'}
